NAME = 'GerOffBiSt: Offene Bibel - Studienfassung'
BOOK = 'Psalms'

CHAPTERS = {
    1: {
        1: '[Wie] glücklich (gesegnet) [ist] der Mensch (Mann), der nicht dem Rat (den Plänen) der Gottlosen (Übeltäter) folgt (gefolgt ist), {und} nicht auf (mit) dem Weg der Sünder steht (betritt; gestanden hat) und nicht an dem Ort (auf dem Sitz, im Kreis) der Spötter sitzt (saß),',
        2: 'sondern am Gesetz (Weisung, Tora) JHWH s {seine} Freude (Verlangen, Lust) [hat] und über sein Gesetz Tag und Nacht nachdenkt (grübelt; leise liest oder rezitiert; nachdenken wird).',
        3: '{Und (Dann) } Er ist (wird sein) wie ein Baum, gepflanzt an Wasserkanälen (Wasserbächen), der seine Frucht bringt (gibt; bringen wird) zu seiner Zeit und dessen Blätter nicht welken. Und alles, was er tut, gedeiht (gelingt; wird gedeihen).',
        4: 'Nicht so die Gottlosen (Übeltäter)! {sondern (vielmehr) } [Sie sind] wie Spreu, die [der] Wind wegbläst (wegblasen wird).',
        5: 'Deshalb bestehen (stehen auf; werden bestehen) Gottlose nicht vor dem (nicht im) Gericht und Sünder [nicht] in der Versammlung der Gerechten.',
        6: 'Denn (ja) JHWH kennt (wacht über) den Weg der Gerechten, aber (und) der Weg der Gottlosen (Übeltäter) führt ins Verderben (vergeht).',
    },
    2: {
        1: 'Warum (wozu) verschwören sich (befinden sich in Unruhe, murren; haben sich verschworen) [die] (heidnischen) Völker (Nationen), und [warum] schmieden (werden schmieden) [die] Völker (Volksgruppen) vergeblich Pläne (Vergebliches, Nichtiges) (knurren, grummeln sie)?',
        2: '[Warum] stellen die Könige der Erde (des Landes; irdischen Könige) sich [zum Kampf] auf (lehnen sich auf, leisten Widerstand; stellen sich [gerade] auf, werden sich aufstellen) und [warum] verbünden (stellen) sich (haben sich verbündet) die Herrscher gegen JHWH und gegen seinen Gesalbten:',
        3: '„Wir wollen (lasst uns, zerreißen wir doch) ihre Fesseln (Bande) zerreißen und ihre Stricke (Bande) von uns abwerfen!“',
        4: 'Der im Himmel thront (sitzt, wohnt), lacht (wird lachen) [über sie], [der] {mein} Herr (Adonai) spottet (verhöhnt; wird spotten) über sie.',
        5: 'Dann (daraufhin) spricht er (wird er sprechen) zu ihnen in seinem Zorn und mit (in) seinem Zornesbrennen (brennenden Zorn, seiner Zornesglut, Heftigkeit) erschreckt (wird erschrecken) er sie:',
        6: '„ {und} Ich selbst (ich aber) habe meinen König auf Zion, meinem heiligen Berg, eingesetzt (geweiht; setze ein).“',
        7: 'Ich will (Lass mich) bezüglich (über, in Hinsicht auf, bezüglich) der Anordnung (Einsetzungsurkunde, Königsprotokoll, Gesetz) JHWH s bekannt machen (rezitieren, berichten, Rechenschaft ablegen, erzählen): Er hat zu mir gesagt: Du [bist] mein Sohn. „Ich selbst habe (zeuge) dich heute (an diesem Tag) gezeugt.',
        8: 'Bitte mich darum (verlange/fordere [es] von mir), dann (und) gebe (werde geben) ich dir ([die]) (heidnischen) Völker (Nationen) [als] deinen Erbbesitz und [als] dein Eigentum (Besitz) die Enden der Erde (die ganze Welt)!',
        9: 'Du wirst (sollst, kannst; zerschmettere) sie mit einem eisernen Zepter (Stab) (Zepter aus Eisen) zerschmettern (weiden), wie Töpferware wirst (sollst, kannst; zerschlage) du sie zerschlagen (zerschmeißen).“',
        10: 'Darum (und nun), [ihr] Könige, handelt verständig (kommt zur Einsicht); lasst euch warnen (zurechtweisen), [ihr] Herrscher (Richter) der Erde (des Landes)!',
        11: 'Dient JHWH mit (in) Furcht (Ehrfurcht) und fürchtet euch (jauchzt, zittert, heult, kehrt um?) mit (in) Zittern!',
        12: 'Rüstet ehrlich ab (Küsst [den] Sohn), damit er nicht (sonst) zornig wird und ihr [auf eurem] Weg umkommt, denn leicht (schnell, bald) entflammt (entbrennt) sein Zorn (Gesicht, Nase). Glücklich (gesegnet) [sind] alle, die sich bei (in) ihm bergen (Zuflucht suchen)!',
    },
    3: {
        1: "''Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David.'' ''Während (Als) er floh vor Absalom, seinem Sohn.''",
        2: 'JHWH! Wie zahlreich (wie sehr vermehrt) [sind] meine Feinde! [Wie] zahlreich (wie sehr vermehrt) [sind] meine Gegner (die, die sich gegen mich erheben)!',
        3: '[Wie] zahlreich (wie sehr vermehrt) [sind], die über meine Seele (über mich) sagen: „Nicht [ist] (Es gibt keine) Rettung (Hilfe, Sieg) für ihn durch (trotz) Gott!“{Sela}',
        4: 'Doch du, oh JHWH, [bist] ein Schild um mich (bist Schutz für mich, schützt mich), [du bist] mein Mächtiger (mein Herrlicher, mein Ansehen, meine Herrlichkeit) und der, der meinen Kopf (mich) erhebt (erhöht).',
        5: '[Sooft (Wann immer)] ich [mit] meiner Stimme JHWH anrufe (anrief), antwortet (antwortete, erhörte) er mir von seinem heiligen Berg (vom Berg seiner Heiligkeit). {Selah}',
        6: '[Wenn] ich mich hinlege und schlafe ([wenn] ich einschlafe), erwache ich, denn JHWH hilft mir (unterstützt mich, stützt mich)!',
        7: 'Ich fürchte mich nicht vor [den] Myriaden von Kriegern, die sich ringsum niedergelassen haben wider mich.',
        8: 'Erhebe dich, JHWH; rette mich, mein Gott! {Ja!,} Zerschlage (Schlage auf) all meinen Feinden den Kiefer (Backe); die Zähne der Frevler zerschmettre! Bei JHWH [ist (sei)] die Rettung (Hilfe, Sieg); auf deinem Volk [ist (sei)] dein Segen. {Selah}',
    },
    4: {
        1: "''Für den Chorleiter (Dirigenten, Singenden, Musizierenden). Mit Saitenspiel (Flötenspiel) '' ''Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David.''",
        2: 'Wenn (weil) ich rufe antworte mir (erhöre mich), oh du mein wahrer Gott (mein gerechter Gott, Gott meines Heils, Gott meiner Gerechtigkeit)! In der Enge (Not) schaff mir (hast geschaffen) Weite (hilf mir in meiner Not) Erbarme dich meiner und höre (erhöre) mein Flehen (Gebet)!',
        3: '{Männer} Wie lange [ist] mein Herrlicher (Gott, meine Ehre) geschmäht (zum Schimpf)? [Wie lange] wollt ihr Nichtiges (Leeres, Abgötter) lieben? [Wie lange] wollt ihr Lügen (-gebilde, Götzen) anflehen (suchen)? {Sela}',
        4: 'Wisst, dass JHWH scheidet (wirkt Wunder an, handelt wunderbar an) den ihm Frommen (seinem Frommen); JHWH wird hören (erhören), wenn ich zu ihm rufe.',
        5: '[Wenn ihr] unruhig seid (seid unruhig!, Zittert!): sündigt nicht! [Wenn ihr] in euren Betten in euren Herzen sprecht (Sprecht!): schweigt! {Sela}',
        6: 'Opfert Opfer dem wahren [Gott] (Opfer der Gerechtigkeit, richtige Opfer) Und vertraut auf JHWH!',
        7: '[Während] viele sagten: „Wer wird uns Gutes erfahren (sehen) lassen (Lass uns Gutes erfahren!) [Wo doch] geflohen ist von über uns das Licht deines Angesichts, oh JHWH!“',
        8: 'Du hast gegeben (erfüllt, gib!) Freude in mein HerzZur Zeit (mehr als zur Zeit), als {ihr} Korn und {ihr} Wein zahlreich war (wurde). In Frieden kann (werde) ich mich hinlegen und sofort einschlafen denn du, oh JHWH, lässt mich ruhen (wohnen) allein (ungestört), [und] in Sicherheit (sicher).',
    },
    5: {
        1: "''Für den Chorleiter (Dirigenten, Singenden, Musizierenden). Zu Flötenspiel (nach „das Erbe“).'' ''Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David.''",
        2: 'Meine Worte höre (erhöre mich), JHWH! achte auf (erhöre) mein Flehen (Grübeln, Murmeln)!',
        3: 'Lausche auf (Erhöre) mein Geschrei (Rufen, Stimme) um Hilfe! Mein König und mein Gott: {Oh,} (weil) zu dir werde ich (will ich) rufen.',
        4: 'JHWH: [Schon] am Morgen (jeden Morgen, Morgen) wirst (sollst, höre!) du meine Stimme hören, [Schon] Am Morgen (jeden Morgen, Morgen) werde (will) ich zu dir beten (dir [Opfer/Gebete] bereiten, mich bereit machen für dich) und [auf dich] warten.',
        5: '{Oh!} (Weil) Du [bist] kein Gott, dem Böse (Böses) gefallen (der Böses will); es dürfen (werden) nicht wohnen bei dir Schlechte (Schlechtes);',
        6: 'es dürfen (werden) nicht stehen Frevler (Angeber, Törichte, Preisende) vor deinen Augen. (Weil) Du hasst alle Tuer von Unheil (Unholde):',
        7: 'Du wirst vernichten Sprechende von Lügen (Lügner) Männer der Bluttat (Gewaltverbrecher) und Männer des Betrugs (Betrüger) verabscheut (verabscheust du,) JHWH.',
        8: 'Ich dagegen darf in der Menge deiner Gnade (in deiner großen Gnade/Treue/Liebe) in dein Haus kommen; ich darf [dich] in (zu) deinem heiligen Tempel (im Tempel deiner Heiligkeit) anbeten in deiner Furcht.',
        9: 'JHWH, führe (begleite mich schützend, schütze) mich in deiner Gerechtigkeit (Wahrhaftigkeit, Wohlwollen, du Gerechter) um meiner Feinde willen (wegen meiner Feinde) ebne vor mir (vor meinen Augen) deinen Weg (deine Weisung, den Weg zu dir).',
        10: 'Weil in seinem (ihrem) Reden (Mund) nichts Aufrichtiges ist, [Sei] ihr Inneres [ihr] Verderben (Böses, sie sind verdorben/böse). [Ihr] (ein) offenes Grab (Tod) [sei (ist)] ihre Kehle, [Weil] sie ihre Zunge glätten (Mit ihrer Zunge sind sie heuchlerisch, sie sind Heuchler).',
        11: 'Lass sie büßen (bestrafe sie), Gott! Lass sie untergehen (sie sollen untergehen) wegen ihrer Pläne (Ränke)! Wegen der Menge ihrer Sündenschuld (Sünden; wegen ihren vielen/großen Sünden) treibe sie fort (verbanne sie)! Sie haben dir ja nicht gehorcht (haben gegen dich rebelliert, gehorchen dir nicht).',
        12: 'Alle werden (sollen) sich freuen, die bei dir Zuflucht suchen! Für immer werden (sollen) sie jubeln {und du beschützt (deckst) sie}! Es werden (sollen) jauchzen über dich, die deinen Namen lieben (dich lieben, dich verehren)! Denn du wirst segnen (bist es, der segnen wird), den Gerechten (die Gerechten) JHWH; [du bist es, der] [sie schützen wirst (decken wirst)] wie mit einem Schild; [du bist es, der] sie mit Huld krönen wird (begünstigen wird).',
    },
    6: {
        1: "''Für den Chorleiter (Dirigenten, Singenden, Musizierenden) ''. ''Zum Saitenspiel (auf Saiteninstrumenten) [vorzutragen] von Basstimmen'' ''Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David.''",
        2: 'JHWH, nicht in deinem Zorn strafe (züchtige) michUnd nicht in deinem Grimm züchtige mich.',
        3: 'Sei mir gnädig (erbarme dich meiner), JHWH, denn ich [bin] schwach (ermattet).Rette mich (heile mich), JHWH, denn erschrocken sind (es zittern, es vergehen) meine Knochen (ich)',
        4: 'Und meine Seele (mein Leben) ist sehr erschrocken (vergeht sehr). Und du, JHWH, wie lange [noch] (bis wann)...?',
        5: 'Kehre um, JHWH! Rette meine Seele (mich)!Errette (hilf) mich um deiner Barmherzigkeit (Huld, Liebe, Güte) willen!',
        6: 'Denn es ist kein (findet nicht statt) dich-Loben (Gedenken an dich) im Totenreich (Tod) Und wer wird dich preisen im Scheol?',
        7: 'Ich bin ermüdet durch mein Schluchzen (Seufzen),ich überflute (lasse schwimmen) jede Nacht [mit meinen Tränen] mein Bett,mit meinen Tränen weiche ich [jede Nacht] mein Lager auf.',
        8: 'Schwach geworden (dunkel geworden, geeitert, angeschwollen, hochmütig?) vor Kummer (Gram) sind meine Augen,Ich bin gealtert wegen (sie sind gealtert wegen) all meiner Feinde (wegen all meinem Leid/meiner Not).',
        9: 'Weicht von mir, all [ihr] Frevler! {Ja!,} (denn) gehört (erhört) hat JHWH den Klang meines Weinens,',
        10: 'Gehört (erhört) hat JHWH mein Bitten; JHWH wird mein Gebet (Bittgebet) annehmen: All meine Feinde werden (sollen) sich schämen (zunichte werden) und sehr erschrecken (vergehen),Sie werden (sollen) umkehren (von mir ablassen, wieder?, sterben?) [und] sich plötzlich schämen (zunichte werden).',
    },
    7: {
        1: "Ein ''Shiggajon'' von (für, über, nach Art von) David, das er JHWH sang wegen der Reden Kuschs, des Benjaminiten.",
        2: 'JHWH, mein Gott, ich suche Schutz bei dir (auf dich setze ich mein Vertrauen): Hilf mir vor all meinen Verfolgern und rette mich,',
        3: 'Damit er nicht meine Seele (mich) zerreißt wie ein Löwe, [Sie (mich)] zerfleischt, ohne dass jemand [sie (mich)] rettet!',
        4: 'JHWH, mein Gott, wenn ich dies getan habe, wenn Unrecht an meinen Händen [ist]',
        5: 'Wenn ich Böses tat dem, der es mir [nun] vergilt (meinem Verbündeten?),und [wenn] ich grundlos meine Gegner (die, die grundlos meine Gegner [sind]) bedrängte (rettete?),',
        6: 'dann verfolge [mein] Feind meine Seele (mich) und erreiche [sie] und trete meine Seele (mich) zu Boden und lasse meine Ehre (mich) im Staub wohnen! {Selah}',
        7: 'Steh auf, JHWH, in Deinem Zorn! Erhebe Dich gegen die Wut meiner Feinde (in [Deiner] Wut auf meine Feinde) Und erwache, mein Gott (Und erwache zu mir hin?), [der] du das Recht eingesetzt hast!',
        8: '{Und} die Versammlung der Völker umgebe dichUnd über sie kehre zur Höhe zurück!',
        9: 'JHWH richte die Völker Schaff [auch] mir Recht, JHWH, gemäß meiner GerechtigkeitUnd gemäß meiner Unschuld, [die] auf mir [ist]!',
        10: 'Ach, es möge enden Böses von Frevlern (böse Frevler, Bosheit von Frevler?), [Aber] Gerechte mögest du sicher stehen lassen. Der gerechte Gott prüft Herz und Nieren,',
        11: '[Darum] [Ist] mein Schild auf mir (auf) Gott, der Retter [derer, die] redlichen Herzens [sind].',
        12: 'Gott [ist] ein gerechter Richter, [Darum] [ist] er [auch] ein Gott, [der] jeden Tag zürnt:',
        13: 'Wenn man sich nicht bekehrt, [sondern] sein Schwert wetzt,Seinen Bogen spannt und ihn aufrichtet -',
        14: 'für sich [selbst] richtet man [dann] die tödlichen Waffen [Und] macht seine Pfeile zu brennenden.',
        15: 'Wenn (siehe) man Frevel empfängt,Geht man mit Bosheit schwanger und gebiert - Trug (und gebiert Lügen).',
        16: 'Gräbt man ein Loch und hebt es aus -Fällt man [selbst] in die Grube, [die] man machen wollte.',
        17: 'Jemandes Bosheit kehrt auf seinen [eigenen] Kopf zurückUnd auf seinen [eigenen] Scheitel kommt jemandes Untat hinab. Ich will JHWH ob (gemäß) seiner Gerechtigkeit preisenUnd spielen dem Namen JHWH s, des Höchsten!',
    },
    8: {
        1: 'Für den Chorleiter (Dirigenten, Singenden, Musizierenden) nach der Melodie „Gittith“(nach dem Kelterlied, auf gathitischem Instrument, auf der Gittith). Ein Psalm (begleitetes Lied) von (für) David.',
        2: 'JHWH, unser Herr, wie herrlich (mächtig) [ist] dein Name (bist du) auf der ganzen Erde (im ganzen Land)! {welche} Deine Hoheit (Majestät, Pracht, Du) wird gepriesen im Himmel (den Himmeln, über dem Himmel)',
        3: 'Aus dem Mund von (Wegen der, Wegen dem dem Klagen der) Babies und Säuglingen hast du ein Bollwerk (Kraft, Macht, Schutz, Festung; Lob) errichtet (grundgelegt) um deiner Gegner willen, um [dem] Feind und [dem] Rachgierigen (Rächern, Rachsüchtigen) ein Ende zu bereiten (um sie zum Schweigen zu bringen, zu vernichten).',
        4: 'Sooft (wenn) ich deinen Himmel sehe (betrachte, zu deinem Himmel sehe), [das] Werk ([die] Werke) deiner Finger (dein mächtiges Werk, dein Werk), Mond und Sterne, die du bereitet (festgemacht, fertiggemacht, eingesetzt) hast,',
        5: '[denke ich (sage ich, rufe ich):] Was [ist das] Menschlein (der Mensch, die Menschheit, der Sterbliche), dass du dich seiner erinnerst (dich um es kümmerst) und was [das] Menschenkind (der Mensch, der Sohn des Menschen, das Kind des Menschen, der Menschensohn), dass du es beachtest (auf es achtest, für es sorgst)?',
        6: '[Nur] ein Stäubchen (ein bisschen, nur wenig) ließest du ihm fehlen zu (ließest ihn geringer sein als) Gott (Göttern, Engeln, himmlischen/übernatürliche Wesen), um ihn mit Herrlichkeit (Hoheit, Würde, Ehre) und Pracht zu krönen (segnen, hast ihn mit Herrlichkeit und Pracht gekrönt).',
        7: 'Um ihn herrschen zu lassen (und machtest ihn zum Herrscher / Herrn, um ihn als Herrscher / Herrn einzusetzen) über das Werk deiner Hände (Macht) hast du ihm alles (alle Dinge) zu Füßen gelegt.',
        8: 'Schafe (Herden) und Rinder (Vieh, Viehzeug, Kleinvieh und Großvieh) allesamt (alle) und auch (sogar) die Tiere des Feldes (Feld, Land)',
        9: 'die Vögel des Himmels und die Fische des Meeres und (selbst) das, was die Pfade (Wege, Ströme?) des Meeres durchzieht (was im Meer seine Bahnen zieht). JHWH, unser Herr, wie mächtig (majestätisch, glanzvoll) ist dein Name (bist du) auf der ganzen Erde (im ganzen Land)!',
    },
    9: {
        1: "''Für den Chorleiter (Dirigenten, Singenden, Musizierenden) ''. `almut labben '' ([Vorzutragen vom] Vorsteher [über das Ritual] „`almut labben“) '' ''Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David.''",
        2: "['''A'''] Ich will (werde) JHWH preisen (danken, bekennen) mit meinem ganzen HerzenIch will erzählen all' deine Wundertaten.",
        3: 'Ich will mich freuen und jubeln über dich,Ich will deinen Namen (dich) besingen (bespielen), Höchster [, mit den Worten]:',
        4: "['''B'''] „Als meine Feinde zurückwichen,Mussten sie stolpern und vor dir zugrunde gehen,",
        5: 'Denn du hast mir Recht und mir Gerechtigkeit geschafft,saßest (hast dich gesetzt) auf dem Thron als gerechter Richter (, [hast] gerecht gerichtet).',
        6: "['''C'''] Du hast Nationen niedergemacht (gescholten): Einen Schlechten (Schlechte) ließest du zugrunde gehen,Ihren Namen hast du ausgelöscht auf immer und [für alle] Zeit.",
        7: 'Der Feind - vernichtet sind [seine] Ruinen auf ewig;Und Gegner (Städte) hast du entwurzelt (zerstört?), was an sie erinnert, ist zugrunde gegangen. {Sie}',
        8: "['''E''' (?)] [Sie!] Doch JHWH wird für immer thronen.Er hat aufgerichtet seinen Thron zum Gericht,",
        9: 'Um die Welt gerecht zu richten (und er wird die Welt gerecht richten),Gericht zu halten (Gericht halten wird er) über die Völker recht,',
        10: "['''F'''] Damit JHWH sei (und JHWH soll sein) eine Zuflucht für die Bedrückten,Eine Zuflucht für Zeiten der Bedrängnis,",
        11: 'Auf dass zu dir flüchten können (und zu dir werden/können/dürfen flüchten) [jene], die deinen Namen kennen,Weil du nicht im Stich lässt, die dich suchen, JHWH.',
        12: "['''G'''] Singt JHWH, der auf dem Zion thront,Verkündet den Völkern seine Taten!",
        13: 'Denn [wie ein (als)] Sucher von Blut (Denn er sucht Blut,) denkt er an sie,Er vergisst nicht das Rufen der Elenden (Armen).“',
        14: "['''H'''] Sei mir gnädig, JHWH! Sieh auf mein Elend von meinen Hassern,Indem du mich emporhebst ([du], der du mich emporhebst/mich emporgehoben hast/ [allein] mich emporheben kann) von den Toren des Todes,",
        15: 'Damit ich Lobpreisungen auf dich äußern kann in den Toren der Tochter Zionund jubeln kann über [meine] Rettung durch dich [mit den Worten]:',
        16: "['''I'''] „Versunken sind die Nationen im Schacht, [den] sie gemacht haben;Im Netz, das sie versteckt haben, hat sich ihr [eigener] Fuß verfangen!",
        17: 'JHWH hat sich kundgetan, Gericht hat er geübt:Im Werk seiner [eigenen] Hände hat er den Schlechten (hat sich der Schlechte) verstrickt!“{Higgaion Selah}',
        18: "['''J'''] Es mögen Schlechte zur {gen} Scheol zurückkehren,Alle Nationen, die Gott vergessen [haben].",
        19: "['''K'''] Ach!, (Denn) nicht auf immer werde vergessen (wird vergessen werden) der Arme,verderbe (wird verderben) die Hoffnung der Elenden für [alle] Zeit!",
        20: 'Erhebe dich, JHWH! Menschlein (Menschen) sollen nicht stark sein!Die Nationen sollen gerichtet werden vor dir! Setze, JHWH, Furcht in sie (ihnen einen Lehrer vor, gib ihnen eine Lehre)!Es sollen wissen Nationen, dass sie [nur] Menschlein (Menschen) sind! {Selah}',
    },
    10: {
        1: "['''L'''] Warum, o JHWH, willst du fern stehen,Willst du dich verbergen in Zeiten der Bedrängnis? -",
        2: 'In [seinem] Hochmut (Stolz) verfolgt der Schlechte den Elenden (Armen) (im Hochmut des Schlechten verfolgt er den Elenden, durch den Stolz des Schlechten brennt der Elende) Sie werden gefangen durch die Ränke, die sie erdacht haben.',
        3: 'Ach!, (Denn) der Schlechte rühmt seine Seele für [ihre] Lust,Und der Abschneider flucht, verachtet JHWH.',
        4: "Der Schlechte, im Hochmut seiner Nase (in seiner Hochnäsigkeit), [denkt:] „Er sucht nicht!“„Es [gibt] keinen Gott“[sind] all' seine Gedanken.",
        5: "Profan (stark?) sind seine Wege allezeit, Hoch [sind] deine Gesetze (Gerichte), fern von ihm;All' seine Gegner, die schnaubt er an.",
        6: 'Er sagt in seinem Herzen (sagt sich): „Ich werde nicht wanken von Geschlecht zu Geschlecht,So dass (weil; [ich], der) [ich] nicht (nie) [sein werde] im Unglück.“',
        7: '[Von] Fluch ist sein Mund voll und [von] List und Gewalttätigkeit,Unter seiner Zunge [ist] Mühsal und Unheil.',
        8: "Er sitzt im Hinterhalt in Dörfern,Um insgeheim Unschuldige (Wehrlose) zu ermorden (wird... morden). ['''Q'''] Seine Augen spähen nach dem Verfolgten",
        9: 'Er lauert in [seinem] Versteck wie ein Löwe in einer Höhle - Er lauert, um den Elenden zu fassen,Fasst den Elenden, indem er ihn in sein (mit seinem) Netz zieht.',
        10: 'Der bricht zusammen, sinkt niederUnd fällt in die Klauen (durch die Macht) [der] Verfolger.',
        11: 'Er spricht in seinem Herzen (zu sich): „Gott vergisst,Verbirgt sein Gesicht, Sieht nicht auf immer!“',
        12: "['''S'''] Steh auf, JHWH! Mein Gott (Gott), heb deine Hand!Vergiss die Elenden [doch] nicht!",
        13: 'Warum verachtet der Schlechte Gott,sagt in seinem Herzen (sagt sich): „Er sucht nicht!“?',
        14: "['''T'''] Du siehst [doch], ach!, du!, Mühsal und Leid.Untersuche [es], um (indem, so dass) zu geben (man gibt, gegeben wird) [es (ihn)] in deine (mit deiner, aus deiner) Hand. Auf dich kann sich verlassen (wird sich verlassen, wird sich/es dir überlassen) der Verfolgte, [Weil] der Helfer der Waise du bist.",
        15: "['''U'''] Zerbrich den Arm des Schlechten und des Bösen!Suche sein Böses (Unrecht), [bis (so dass)] du [ihn (es)] nicht mehr findest (Sucht man sein Böses, sei es nicht mehr zu finden! Wenn er nach seinem Bösen greift, soll er es nicht finden)!",
        16: '[Weil] JHWH König auf immer und [für alle] Zeit [ist],Verderben Nationen aus seinem Land (seiner Erde).',
        17: "['''V'''] Du hörst das Verlangen der Elenden, JHWH.Auf die Ausrichtung ihres Herzens (richte ihr Herz aus, richte ihr Herz auf?) lass (du wirst, es soll/wird) horchen dein Ohr,",
        18: 'um Recht zu schaffen (indem du Recht schaffst) der Waise und dem Unterdrückten:Es soll nicht weiterhin so weitergehen, dass ein Menschlein aus Erde Schrecken verbreitet (Menschlein aus dem Land herausgeschreckt werden).',
    },
    11: {
        1: "''Für den Chorleiter (Dirigenten, Singenden, Musizierenden; [Vorzutragen vom] Vorsteher [über das Ritual]) ''. ''Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David.'' Auf JHWH vertraue ich (zu JHWH fliehe ich/bin ich geflohen). Wie [könnt] ihr [da] zu mir (zu meiner Seele) sagen:„Flieht auf euren Berg [wie] ein Vogel! ([wie] Vögel; flieh auf euren Berg, Vogel!, flieh/flieht ins Gebirge wie ein Vogel/wie Vögel!)",
        2: 'Denn siehe, die Bösen wollen den Bogen spannen,Sie wollen den Pfeil auf die Sehne legenUm im Dunkel auf die zu schießen, die aufrechten Herzens sind.',
        3: 'Ja, (denn) [selbst] die Fundamente sollen (werden) eingerissen werden - Was [also] tut der Gerechte?“',
        4: 'JHWH, [der] in seinem heiligen Tempel (Palast) [ist], (JHWH ist in seinem heiligen Tempel; ist JHWH in seinem heiligen Tempel?) JHWH, [der] im Himmel seinen Thron [hat] (JHWH s Thron ist im Himmel; ist JHWHs Thron im Himmel?) - Seine Augen blicken,Seine Augen prüfen die Menschensöhne.',
        5: 'JHWH, der Gerechte, prüft. (JHWH [ist] gerecht. Er prüft.) - Und den Bösen und den Gewalt Liebenden hasst er (hasst seine Seele).',
        6: 'Er wird (soll) regnen lassen auf [die] Bösen Schlingen (Kohle?):Feuer, Schwefel und gewaltiger (glühender) Wind [ist] der Anteil ihres Bechers.',
        7: 'Weil JHWH gerecht (der Gerechte) ist (denn JHWH ist gerecht.), Gerechtigkeit liebt (liebt er Gerechtigkeit.),Wird ein Aufrechter sein Gesicht sehen (wird sein Gesicht auf einen Aufrechten sehen?).',
    },
    12: {
        1: "''Für den Chorleiter (Dirigenten, Singenden, Musizierenden) ''. `al-hascheminit '' ([Vorzutragen] von Basstimmen; [Vorzutragen vom] Vorsteher über [das Ritual] „hascheminit“) ''. ''Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David.''",
        2: 'Hilf (Rette), JHWH, denn [der] Fromme (Frömmigkeit) endet (ist geendet),Denn [die] Treuen (Treue) gehen zugrunde (sind zugrunde gegangen) unter den Menschenkindern!',
        3: 'Erlogenes sagt jeder seinem Nächsten; [Mit] glatter Lippe, mit Herz und Herz sprechen sie!',
        4: 'JHWH möge vernichten (abschneiden) alle glatten Lippen, [Die] Zunge, die Großes (Vermessenes) spricht,',
        5: '[Sie], sie [vorher] gesagt haben: „Mit unserer Zunge sind wir stark (unserer Zunge verschaffen wir Stärke?, über unsere Zunge herrschen wir?) Unsere Lippen [sind] mit uns (gehören uns) - wer [also] [will da] Herr über uns [sein]?“',
        6: '„Wegen der Gewalt gegen [die] Elenden, wegen dem Ächzen [der] Armen - Jetzt werde (will) ich mich erheben“, möge (wird) JHWH sprechen (spricht JHWH?);„Ich werde (will) in Sicherheit bringen (ins Heil versetzen) [den, der] danach seufzt (gegen den man schnaubt, will seinen Zeugen in Sicherheit bringen, will ihm zum Heil einen Zeugen stellen).“',
        7: '[Und diese] Aussagen von JHWH [mögen sein (sind)] reine Aussagen,Silber, [das] geläutert [wurde]???, [Das] siebenfach in die Erde veredelt [wurde].',
        8: 'Du, JHWH, mögest (wirst) sie behüten (sie (=die Worte) halten?),Mögest (wirst) ihn schützen vor diesem (dem) Geschlecht auf ewig (diesem Geschlecht, das ewig [währt])! Rings (im Kreis) gehen Böse einher,Da Verachtenswertes hoch ist (wird) bei den Menschenkindern.',
    },
    13: {
        1: 'Für den den Chorleiter (Dirigenten, Singenden, Musizierenden). Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David.',
        2: 'Bis wann (wie lange), JHWH, wirst (willst) du mich [so] gänzlich (für immer, fortwährend) vergessen? Bis wann (Wie lange) wirst (willst) du dein Gesicht vor mir verbergen?',
        3: 'Bis wann (Wie lange) muss (werde) ich Pläne (Auflehnung?, Schmerzen?, Kummer?, Sorgen?) in meine Seele legen, Wobei ([Bis wann (wie lange)] [wird sein/muss ich legen]) Kummer in meinem Herzen [ist] [sogar] am Tag (täglich?, den ganzen Tag?, Tag [und Nacht]? {am Tag}?)? Bis wann (Wie lange) wird (darf) mein Feind (meine Feinde) mir überlegen sein (über mich erhoben sein, über mich erhaben sein, über mich triumphieren)?',
        4: 'Schau ([auf mich])!, antworte mir, JHWH! Mein Gott, lass meine Augen leuchten, Damit ich nicht zum Tod entschlafe (im Tod schlafe, tot schlafe, den [Schlaf des] Tod [es] schlafe)!',
        5: 'Damit mein Feind (meine Feinde) nicht sagen kann: „Ich habe ihn übermocht (Ich habe ihn ausgetilgt?, Ich habe es geschafft?)!“Mögen auch meine Bedränger jubeln (Meine Bedränger jubeln), weil (wenn, dass) ich wanke (wanken werde) -',
        6: 'vertraue ich dagegen (Ich dagegen vertraue) auf deine Gnade (Güte): Mein Herz (Ich) soll [dereinst] jubeln über deine Hilfe, Ich will JHWH (dich) [dereinst] besingen: {denn} (denn, ja!, sobald) „Er hat (Du hast) an mir [Gutes] getan!“',
    },
    14: {
        1: "''Für den Chorleiter (Dirigenten, Singenden, Musizierenden; [Vorzutragen vom] Vorsteher [über das Ritual]) ''. ''Von (für, über, nach Art von) David.'' Es sagt (sagte) [der] Narr in seinem Herzen (es sagte sich der Narr):„Es gibt keinen Gott!“Sie begehen, verbrechen (begingen, verbrachen) Übeltat [Es gibt (gab)] keinen, [der] Gutes tut.",
        2: 'JHWH beugte (beugt) sich (blickt?) vom Himmel herab Über [die] Menschenkinder, Um zu sehen, [ob] es gibt einen Klugen,Einen Gott-Sucher (einen Klugen, [der] Gott sucht):',
        3: '„Die Gesamtheit ist (war) abgefallen,Sämtlich sind (waren) sie verdorben. Keinen [gibt (gab) es], [der] Gutes tut;Keinen. Auch nicht einen [einzigen].',
        4: 'Wissen [denn] nicht [s] alle Übel-Täter, [Die] mein Volk fressen? Sie fressen Brot, [Doch] JHWH rufen sie nicht an.“',
        5: 'Da erschraken sie einen Schrecken,Weil Gott mit [dem] gerechten Geschlecht [war]:',
        6: '„ [Die] Plän [e] des Armen wollt ihr zuschanden machen,Doch JHWH [ist] sein Schutz!“',
        7: 'Möge es doch vom Zion Rettung für Israel geben! Wenn JHWH das Geschick (die Gefangenschaft) seines Volkes wendet,Möge Jakob jubeln, Israel sich freuen!',
    },
    15: {
        1: 'Ein Lied von (für, über, nach Art von) David. JHWH, wer darf (wird) gasten (Gast sein) in deinem Zelt (in deinen Zelten) Und ({und}) wer darf (wird) wohnen auf deinem heiligen Berg (auf dem Berg deiner Heiligkeit)?',
        2: '„ [Wer] redlich wandelt Und Gerechtes (recht) tut Und Wahres sagt (denkt) in seinem Herzen (ausspricht, [was] wahrhaft in seinem Herzen [ist]),',
        3: 'Nicht Verleumdung auf seiner Zunge [hatte], ([Und]) Nicht tat seinem Genossen Schaden (Böses) Und Schande nicht trug wegen seinem Nächsten (nicht lud auf seinen Nächsten?),',
        4: 'Verachtet [den] in seinen Augen Verworfenen ([bei dem] verachtet [ist der] in seinen Augen Verworfene; in seinen [eigenen] Augen verachtet, verworfen [ist]) Und (aber) den JHWH -fürchtigen ehrt, Schwor dem Genossen (zu schaden, zum Schaden?) Und nicht ändert,',
        5: 'Sein Geld nicht verliehen (gegeben) hat gegen ZinsUnd Geschenke (Bestechungsgelder) gegen einen Unschuldigen nicht genommen hat. [Wer] dies tut, Wird auf ewig nicht wanken.“',
    },
    16: {
        1: "''miktam'' von (für, über, nach Art von) David. Schütze mich, Gott,denn ich berge mich bei dir (vertraue dir)!",
        2: 'Ich sage (du sagst) zu (über, was... angeht) JHWH: „Mein ({Mein}) Herr [bist] du!Mein Wohlergehen (Glück) [ist] nicht außer durch dich (nicht über dir?)!“,',
        3: 'Zu den (über die, was... angeht) Heiligen, die im Land (auf der Erde) [sind]: „Diese, die (meine) Herrlichen: Mein ganzes Wohlgefallen [richtet sich] auf sie!“',
        4: 'Es sollen (werden) sich vermehren die Schmerzen (Götzenbilder) derer (es vermehren sich ihre Schmerzen die), die einem anderen (die anderen) nacheilen (?, umwerben?),Nicht werde ich libieren ihre Blutlibationen (ihre Libationen mit [meiner] Hand),Nicht werde ich heben ihre Namen auf meine Lippen!',
        5: 'JHWH [ist] das Teil meiner Zuteilung und meines Bechers,Zieher meines Lossteins (Erhalter meines Loses).',
        6: 'Schnüre fielen mir auf Liebliches (liebliches [Land]),ja, mein Erbbesitz (der Erbbesitz) dünkt mich schön!',
        7: 'Ich will preisen JHWH, der mich berät,ja, [selbst] in den Nächten belehren (züchtigen) mich meine Nieren.',
        8: 'Ich setze mir JHWH vor mich beständig;Denn [ist er] zu meiner Rechten, werde ich (ja, [ich setze ihn] zu meiner Rechten, ich werde; weil er zu meiner Rechten ist. Ich werde) nicht wanken.',
        9: 'Darum freut sich mein Herz und jubelt meine Leber (Herrlichkeit),Ja, [selbst] mein Fleisch wird wohnen (ruhen) in Sicherheit.',
        10: 'Denn du wirst meine Seele (mich) nicht dem Scheol überlassen (im Scheol lassen),Du wirst nicht erlauben, dass dein Frommer (deine Frommen) die Grube (die Verwesung) sieht.',
        11: 'Du wirst (sollst) mir kundtun (mich erkennen lassen) den Weg des Lebens (zum Leben): [Die] Fülle (Sättigung) der Freuden ([ist]) bei deinem Angesicht, [Die] Lieblichkeiten (Freuden, Annehmlichkeiten) ([sind]) in deiner Rechten allezeit!',
    },
    17: {
        1: "''Ein Bittgebet. Von (für, über, nach Art von) David.'' Höre, JHWH, Gerechtigkeit:Horch mein Schreien, Lausche meinem BittgebetVon Nicht-Trug-Lippen!",
        2: 'Von dir (von vor deinem Gesicht) möge (wird) mein Recht ausgehen (aufstrahlen),Deine Augen mögen (werden) schauen Aufrichtigkeit {en} (richtig, unparteiisch):',
        3: 'Testestest du (du testestest) mein Herz, Prüftest du (du prüftest) [mich (es)] [selbst] bei Nacht, probtest du (du probtest) mich, Würdest (wirst, könntest) du nicht finden Ränke an mir (Plan, Schandtat, ich habe geplant), [die] nicht meinen Mund überschreiten dürfte.',
        4: "Was die Taten (das Tun) des Menschen gegen das Wort deiner Lippen angeht:''Ich'' habe geachtet die Wege des Gebots (Gewalttätigen),",
        5: 'Es hielten meine Schritte sich in deinen SpurenNicht wankten meine Tritte.',
        6: 'Ich rufe zu dir, damit du mich erhörst (denn du wirst mich erhören), Gott!Neige dein Ohr (dein Lauscher) zu mir, höre meine Rede!',
        7: 'Wirke wunderbar (erweise) deine Huld, [oh] Retter (Heiland) der sich ([zu dir]) Flüchtenden (der ([auf dich]) Hoffenden) Vor sich Erhebenden wider deine rechte Hand!',
        8: 'Behüte mich wie ein Augenmännlein (die Pupille) des Augenmädchens (, die Pupille),Im Schatten deiner Flügel birg mich',
        9: 'Vor Frevlern, die mir Gewalt antun, [Vor] meinen Feinden, die gierig (vor meinen Todfeinden, die?) mich umzingeln {wollen}!',
        10: '[Mit] Fett verschließen sie [ihr Herz], [Mit] ihrem Mund reden sie stolz.',
        11: 'Sie verfolgen mich (unsere Schritte, sie warfen mich hinaus, sie tadelten mich), jetzt umgeben sie mich,Ihre Augen setzen sie [darauf], [mich] zur Erde niederzustrecken;',
        12: 'Sie sinnen gegen mich (sein Aussehen ist wie das eines) wie ein Löwe, [der] zu reißen giert,Ein Junglöwe, [der] im Versteck sitzt (auf der Lauer liegt)!',
        13: 'Erhebe dich, JHWH, tritt ihm (seinem Gesicht) entgegen,Rette (befreie) meine Seele (mich) vor dem Frevler! Dein Schwert [sei]',
        14: 'von den Toten (Männern),Deine Hand, JHWH, [sei] von den Toten (Männern), [die] ohne Dauer (Welt) [waren],Ihr Teil im Leben! [Mit] deinem Aufgesparten fülle ihren MagenSättigen sollen sich [auch] ihre Kinder,Und diese (ja, sie) sollen überlassen ihren Rest ihren Säuglingen!',
        15: "''Ich'' [aber] will (werde) als Gerechter (Gerechtfertigter, in/durch Gerechtigkeit) dein Gesicht schauen,Will mich sättigen beim Aufwachen an deinem Bild.",
    },
    18: {
        1: "''Für den Chorleiter. Vom Diener JHWH s, von David, welcher sprach zu JHWH die Worte dieses Lieds am Tag, als JHWH ihn rettete aus der Handfläche all seiner Feinde und aus der Hand Sauls.''",
        2: "''Und er sagte:'' „Ich will dich lieben, JHWH, meine Stärke!",
        3: 'JHWH [ist] mein Fels und meine Burg und mein Retter,Mein Gott [ist] (,) mein Berg, zu dem ich fliehe (auf den ich vertraue),Mein Schild, das Horn meiner Rettung, meine Klippe (Festung)!',
        4: 'Als Lobenswerten will ich anrufen JHWH Und von meinen Feinden will (werde) ich gerettet werden.',
        5: 'Es umgaben mich Wogen des Todes,Die Flüsse Belias werden mich erschrecken!',
        6: 'Die Stricke des Scheol umfingen mich, Es ereilten mich die Schlingen des Todes.',
        7: '[Ich sprach:] »In meiner Not will ich anrufen JHWH Und zu meinem Gott will ich schreien. Er soll hören in seinem Tempel meine StimmeUnd mein Schreien soll kommen in seinem Ohr!«',
        8: 'Da wankte und schwankte die ErdeUnd die Pfeiler der Berge bebten und wanktenDenn es loderte in ihm.',
        9: 'Es stieg Rauch aus seiner NaseUnd Feuer fraß aus seinem Mund;Kohlen brannten aus ihm hervor (entbrannten durch es).',
        10: 'Und er öffnete (neigte) den Himmel und stieg herabUnd eine Wolke (Dunkelheit) [war] unter seinen Füßen.',
        11: 'Und er ritt auf einem Kerub und flogUnd schoß herab auf den Flügeln des Windes.',
        12: 'Und er setzte Dunkelheit als seine Bedeckung um sich,Seine Hütte [waren aus] Massen von Wassern in den Wolken des Himmels.',
        13: 'Aus dem Glanz vor ihm gingen ausHagel und Kohlen von Feuer.',
        14: 'Und es donnerte aus dem Himmel JHWH Und Eljon wird geben seine Stimme.',
        15: 'Und er warf seine Pfeile und zerstreute diese,Einen Blitz schoß er und verwirrte er.',
        16: 'Und es wurden gesehen die Betten der Wasser,Es werden bloßgelegt werden die Fundamente der Erde. Durch dein Schelten, JHWH,Durch das Schnauben des Windes deiner Nase.',
        17: '[Ich sprach:] »Er möge (wird) senden aus der Höhe, mich ergreifen,Mich herausziehen aus vielen Wassern,',
        18: 'Es möge mich retten vor meinem Feind der Starke Und vor meinen Hassern, weil sie kräftiger sind als ich!',
        19: 'Sie werden mir entgegentreten am Tag meines Unglücks!« Da wurde JHWH zu meiner Stütze:',
        20: 'Er führte mich ins Weite. [Ich wusste:] »Er wird mich retten, weil er Gefallen hat an mir:',
        21: 'Es wird mich belohnen JHWH entsprechend meiner Gerechtigkeit,Entsprechend der Reinheit meiner Hände wird er mir zurückgeben,',
        22: 'Denn ich wahrte die Wege JHWH sUnd handelte nicht böse von meinem Gott,',
        23: 'Denn all seine Gesetze [waren] vor mirUnd seine Satzungen werde ich nicht von mir stoßen',
        24: 'Und ich verhielt mich gegen ihn perfektUnd ich hütete mich vor meinen Fehlern.',
        25: 'Und es gab JHWH mir zurück entsprechend meiner Gerechtigkeit,Entsprechend meiner Reinheit vor seinen Augen.«',
        26: '[Dem] Bundestreuen gegenüber wirst du dich bundestreu erweisen,Und [dem] perfekten Mann gegenüber wirst du dich perfekt erweisen,',
        27: '[Dem] Reinen gegenüber wirst du dich rein erweisen,Dem Falschen gegenüber wirst du dich verkehrt erweisen.',
        28: 'Du rettest das arme Volk,Doch die Augen Hochmütiger beugst du nieder.',
        29: 'Ja, du bist meine Lampe, JHWH,Mein Gott wird erhellen meine Dunkelheit.',
        30: 'Ja, mit dir werde (kann) ich überrennen (zerschmettern) eine TruppeUnd mit meinem Gott werde (kann) ich eine Mauer überspringen.',
        31: 'Gott - vollkommen [ist] sein Weg. Das Wort JHWH s ist erprobt, Ein Schild [ist] er für alle, die auf ihn vertrauen (die zu ihm flüchten).',
        32: 'Ja, wer ist Gott außer JHWH Und wer ein Berg außer unserem Gott –',
        33: 'Dem Gott, [der] mich stärkt [mit] KraftUnd der meinen Weg perfekt machte,',
        34: 'Der meinen Fuß einer Gazelle gleich machteUnd mich auf meine Höhen stellte,',
        35: 'Der meine Hände für den Kampf trainierte,Um zu stärken [wie] einen Kupferbogen meine Arme!?',
        36: 'Und du gabst mir den Schild der Rettung Und deine rechte Hand wird mich stützenUnd deine Erhörung wird mich vergrößern.',
        37: 'Du wirst weit machen meine Schritte unter mirUnd meine Knöchel wanken nicht.',
        38: 'Ich werde nachjagen meinen Feinden und sie erreichenUnd werde nicht umkehren, bis ich sie zerstört habe.',
        39: 'Ich werde sie zerschmettern und sie werden sich nicht erheben können,Sie werden unter meine Füße fallen!',
        40: 'Und du gürtetest mich mit Kraft für den Kampf,Du wirst beugen [die], die sich [gegen] mich erheben, unter mich!',
        41: 'Und meine Feinde – du gabst mir [ihren] Rücken;Meine Hasser werde ich vernichten.',
        42: 'Sie werden schreien, doch es [wird für sie] nicht geben einen Retter,Zu JHWH, aber er antwortete ihnen nicht.',
        43: 'Ich werde sie zermalmen wie Staub auf dem {Gesicht des} Weg {es},Wie Kot [auf] der Straße werde ich sie ausschütten!',
        44: 'Du wirst mich retten aus den Auseinandersetzungen des Volkes,Du wirst mich einsetzen als Haupt der Heiden,Ein Volk, [das] ich nicht kenne (kannte), wird mir dienen.',
        45: 'Auf Gehörtes des Ohrs [hin] werden sie auf mich hören, {Kinder von } Ausländer {n} werden mir [Ergebung] heucheln (mir schmeicheln),',
        46: '{Kinder von } Ausländer {n} werden vergehen Und sich [selbst] gürten mit ihren Banden.',
        47: '[So wahr] Gott lebt: Gesegnet [sei] mein FelsUnd erhoben werden soll der Gott meiner Rettung,',
        48: 'Der Gott, [der] mir Rache gab (gibt) Und Völker unter mich unterjocht hat,',
        49: 'Der mich meinen Feinden rettet (entkommen lässt),Mich erhöhen wird über die, die sich gegen mich erheben,Der du mich von dem gewalttätigen Mann befreien wirst.',
        50: 'Darum will ich dich preisen, JHWH, [mitten] unter den Heiden,Und deinem Namen singen, Der groß macht das Heil seines KönigsUnd seinem Gesalbten Bundestreue erweist,David und seinen Nachkommen auf ewig. “',
    },
    19: {
        1: 'Für den Chorleiter (Dirigenten, Singenden, Musizierenden). Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David.',
        2: 'Der Himmel verkündet (Die Himmel verkünden) die Herrlichkeit (Lichtglanz, Glorie) Gottes„ und das Walten (Werk) seiner Hände (sein Walten) macht kund das Firmament (Himmelsgewölbe):“',
        3: 'Tag für Tag äußert es (strahlt es hervor, sprudelt es hervor?) Rede (Ein Tag äußert gegenüber [dem nächsten] Tag Rede, Tag für Tag äußert man?),„ Nacht für Nacht lehrt es Kenntnis (Wissen, Weisheit; eine Nacht lehrt [der nächsten] Nacht Kenntnis, Nacht für Nacht lehrt man Kenntnis?).“',
        4: 'Nicht [ist es eine] Rede [und] nicht [sind es] Worte,„ [deren] Klang nicht gehört würde: “',
        5: 'Ihr Klang (Ihre Schnur?, Ihr Ruf?) geht aus über die ganze Erde„ und bis ans Ende der Welt [geht aus] ihr Reden.“Der Sonne (dem Sonnenball) hat er gebaut ([ist (gehört)] dort) ein Zelt aus (an) ihm.',
        6: 'Und sie [ist] wie ein Bräutigam, [der] ausgeht aus seinem Brautzelt (Zelt),„ sie freut sich wie ein Held [darüber (sich darüber freut)], die Bahn zu durchlaufen.“',
        7: 'Am [einen] Ende des Himmels (der Himmel) [ist] ihr Ausgang„ und ihr Abgang [ist] am (ihr Wendekreis [ist (reicht)] bis zum) [anderen] Ende, nichts ist vor ihrer Glut (Hitze, seiner Sonne) verborgen.“',
        8: 'Das Gesetz JHWH s [ist] vollkommen (makellos) - bringt zurück Lebenskraft (gibt neue Lebenskraft, bekehrt {die Seele}); Die Satzung JHWH s [ist] zuverlässig (glaubwürdig) - macht den Einfältigen weise.',
        9: 'Die Weisungen JHWH s [sind] richtig (die richtigen, angenehm) - erfreuen das Herz (erfreuen {das Herz}, erhellen den Geist), Das Gebot JHWH s [ist] lauter (licht) - macht die Augen hell.',
        10: 'Das Wort JHWH s (die Furcht vor JHWH, die JHWH-Religion?) [ist] rein (leuchtend) - besteht in Ewigkeit, Die Rechtssätze JHWH s [sind] Wahrheit (wahr, die wahren) - sind gerecht (im Recht, die rechten) allesamt (und noch dazu sind sie gerecht).',
        11: '[Durch] sie, die begehrenswerter sind als Gold,„ ja, als (und als) reichlich Reingold,“und süßer als Honig„ ja, (und) [als] Honig des Honigs,“',
        12: 'wird auch dein Sklave gewarnt (erleuchtet) {durch sie}.„ In ihrer Befolgung [ist (liegt)] reichlich Lohn.“',
        13: '[Doch] Versehen (versehentliche Fehler) - wer bemerkt sie?„ Von den Verborgenen (ungewollte Sünden) mache mich rein;“',
        14: 'Auch von Vermessenheit (vermessenen Menschen, willentlichen Sünden) halte zurück deinen Sklaven,„ Lass sie mich nicht beherrschen!“Dann werde ich vollkommen (makellos) sein„ Und rein sein von reichlich [großem] Vergehen.“Es seien zum Gefallen die Reden meines Mundes (mein Reden) „ Und das sich-Äußern meines Herzens (meine Äußerungen) vor deinem Gesicht (vor dir) - JHWH, mein Fels und mein Erlöser!“',
    },
    22: {
        1: "''Für den Chorleiter (Dirigenten, Singenden, Musizierenden) ''. ''Nach „Hirschkuh der Mörgenröte“([Vorzutragen vom] Vorsteher [über das Ritual] „Hirschkuh der Morgenröte“).'' ''Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David''",
        2: 'Mein Gott, mein Gott, warum hast du mich verlassen, [Warum] [bist du] fern von meiner Rettung (von meinem Schreien), [von den] den Worten meiner Klage ([warum] [sind] die Worte meiner Klage fern von meiner Rettung; [warum] [bist du] fern von meiner Rettung, [fern von] [meinen] Worten, oh du meine Hilfe)?',
        3: 'Meine Gottheit, ich rufe Tag - doch du antwortest nicht (erhörst mich nicht), Und Nacht - doch [es gibt] nicht Ruhe für mich.',
        4: '[Auf] dich - den Heiligen,Der du thronst über den Lobgesängen Israels (Dabei thronst du doch als der Heilige / über den Lobgesängen Israels; Dabei bist du doch heilig/der Heilige, / thronst über den Lobgesängen Israels) -',
        5: 'Auf dich vertrauten [doch schon] unsere Vorfahren: Sie vertrauten - und du hast sie befreit.',
        6: 'Zu dir schrien sie - und wurden gerettet, Auf dich vertrauten sie - und wurden nicht zuschanden.',
        7: 'Ich aber bin ein Wurm und kein Mensch (Bin ich etwa ein Wurm und kein Mensch!? / Bin ja der Leute Spott...) Der Leute Spott und verachtet vom Volk.',
        8: 'Alle, die mich sehen, verhöhnen mich, Reißen die Lippe [n] auf, schütteln den Kopf [und spotten:]',
        9: '„Wälze (Er hat gewälzt) [es (dich)] auf JHWH! Der wird (soll) ihn retten, Der wird (soll) ihn befreien - er hat ja Gefallen an ihm (er ist ja so gläubig)!“',
        10: 'Ach! (So ists!, Denn) Du [warst] es [doch], der mich aus dem Schoß hervorbrechen ließ,Der mir Vertrauen einflößte (dem ich vertraute) [schon] an der Brust meiner Mutter.',
        11: 'Auf dich bin ich geworfen [schon] vom Mutterleib an, [Schon] von meiner Mutter Schoß an bist du mein Gott.',
        12: 'Sei nicht fern von mir, Denn die Enge (Bedrängnis) [ist] nahe; [Denn] kein Beschützer ist da.',
        13: 'Es umgeben mich mächtige (zahlreiche) Stiere, Gewaltige Baschan [stiere] umringen mich.',
        14: 'Es sperren ihr Maul auf gegen michReißende, brüllende Löwen (Sie sperren ihr Maul gegen mich auf / [wie] ein reißender, brüllender Löwe).',
        15: 'Wie Wasser bin ich ausgeschüttet,Und es sind gelöst all meine Gebeine. Es ist mein Herz wie {das} Wachs -Es zerschmilzt in meiner Brust.',
        16: 'Trocken wie eine [Ton] scherbe ist meine Kraft (Kehle), Meine Zunge klebt mir am Gaumen. [Bald] wirst du mich in den Staub des Todes legen können (Willst du mich in den Staub des Todes legen?).',
        17: 'Ach!, Es umgeben mich Hunde, Eine Rotte von Übeltätern umzingelt (umkreist) mich. Aufgegraben sind ([wie] {der} [ein] Löwe, gebunden sind) meine Hände und Füße.',
        18: 'Zählen kann ich all meine Knochen. Und sie wollen sich weiden, sich an mir ergötzen,',
        19: 'Sie wollen meine Kleider unter sich aufteilenUnd das Los um mein Gewand werfen!',
        20: 'Aber du, JHWH, sei nicht fern,Meine Hilfe, eile zu meiner Hilfe!',
        21: 'Bewahre vor dem Schwert mein Leben, Vor der Gewalt der Hunde mein Einziges!',
        22: 'Rette mich aus dem Rachen der Löwen, Vor den Hörnern der Wildstiere mein Elendes (erhöre mich, du erhörst mich/hast mich erhört).',
        23: 'Ich will deinen Namen meinen Brüdern verkünden, In der Kultgemeinde will ich dich preisen:',
        24: '„Die ihr JHWH fürchtet (verehrt), preist ihn, Alle Nachkommen Jakobs, ehret ihn, Erschauert vor ihm, alle Nachkommen Israels,',
        25: 'Denn er hat nicht verachtet und nicht verabscheut Das Elend des Elenden, Er hat nicht sein Gesicht vor ihm verborgen,Und als er zu ihm schrie, erhörte er ihn!“',
        26: 'Von dir [wird sein] mein Lobgesang in großer Kultgemeinde, Meine Gelübde werde ich vor denen erfüllen, die ihn fürchten (verehren):',
        27: '„Die Elenden sollen essen und satt werden (sollen sich satt essen),Es sollen JHWH preisen, die ihn verehren. Aufleben soll euer Herz für immer!“',
        28: 'Es werden (sollen) [davon] berichten und (Sie werden [davon] berichten und dann werden) zu JHWH umkehren Alle Enden der Erde Und vor dir (vor ihm) werden (sollen) sich niederwerfen Alle Sippen der Völker [mit den Worten:]',
        29: '„ {Ja!} (Ja!, Denn) JHWH s [ist (das)] das KönigtumUnd er [ist (sei)] Herrscher über die Völker.“',
        30: 'Ja, vor ihm werden sich niederwerfen (Es aßen und warfen sich nieder) alle Fetten der Erde,Vor seinem Gesicht sich alle beugen, die in den Staub sinken. Und [wer] seine Seele nicht am Leben erhalten konnte,',
        31: '[bei dem] werden [seine] Nachkommen ihm dienen. Erzählen wird man vom Herrn der Generation, die noch kommen wird Und verkünden seine Gerechtigkeit dem Volk, das noch geboren wird: „Er hat gehandelt (hat [es] vollbracht)!“',
    },
    23: {
        1: 'Ein Psalm (begleitetes Lied) von (für, über, nach Art von) David. JHWH ist mein Hirte. Nichts fehlt mir (wird mir fehlen).',
        2: 'Er sorgt dafür (macht es möglich, erlaubt mir), dass ich mich auf Weiden mit saftigem Gras (grünen/frischen Wiesen/Auen/Weiden) ausruhen (hinlegen, rasten) kann. Zu ruhigen (stillen) Gewässern (einem Gewässer, Gewässern der Rast, natürlichen Tränken, murmelnden Bächen) führt er mich (wird er mich führen).',
        3: 'Meine Lebenskraft (meine Kehle, meinen Lebensatem, mein innerstes Wesen, mich selbst) bringt er zurück (wird er erneuern, erfrischt er). Er führt mich (wird mich führen) auf richtigen Pfaden (Pfaden der Gerechtigkeit) zur [Wahrung] seines Namens (guten Rufs).',
        4: 'Auch wenn ich durch (in) das Tal des Todesschattens (das von tödlicher Gefahr überschattete Tal, das extrem finstere Tal) gehe (gehen werde/muss/sollte, gerate), fürchte (werde ich fürchten) ich keine Gefahr (Unheil, Übel, Unglück, nichts Böses, das Böse nicht, den Bösen nicht), denn du [bist] bei mir. Deine Keule (Rute, Knüppel, Stock) und dein Stab {sie} geben mir Zuversicht (trösten/beruhigen mich, werden mir Zuversicht geben).',
        5: 'Du deckst (bereitest vor, wirst decken) vor mir einen Tisch (eine Matte, ein Festmahl), direkt vor (gegenüber von) meinen Feinden (meines Feindes). Du hast (salbst) meinen Kopf mit Öl (Olivenöl, Fett) gesalbt (erfrischt, eingefettet) Mein Becher [ist] randvoll (fließt über).',
        6: 'Nur (ja, nichts als) Güte (Gutes) und Liebe (Gnade) werden mir folgen (verfolgen mich) [an] allen Tagen meines Lebens, und (und dann, und so) ich werde wohnen (halte mich auf, werde [immer wieder] zurückkehren) im (ins) Haus JHWH s für die Länge meiner Tage.',
    },
    24: {
        1: 'Von (für, in Bezug auf) David – ein Psalm (begleitetes Lied). Dem JHWH ist die Erde und ihre Fülle, [das] Festland und die, die auf ihm wohnen.',
        2: 'Denn er hat sie über Wassern gegründet, und über Strömen wird er sie aufstellen.',
        3: 'Wer dürfte hinaufsteigen auf den Berg JHWH s? Und wer dürfte sich aufrichten am Ort seiner Heiligkeit?',
        4: 'Wer mit reinen Händen und lauterem Herzen nicht seine Seele erhebt nach dem Gehaltlosem, und nicht schwört dem Verrat,',
        5: '[d] er wird Segen erhalten von dem JHWH, und Recht vom Gott seines Heils.',
        6: 'Dies ist die Generation, die nach ihm sucht, die dein Angesicht suchen, Jakob. Sela.',
        7: 'Hebt an ihr Tore euer Oberes, und erhebt euch ihr uralten Tore, und der König der Ehre wird einziehen.',
        8: 'Wer ist der König der Ehre? JHWH, stark und gewaltig, JHWH, gewaltig im Kampf.',
        9: 'Hebt an ihr Tore euer Oberes, und erhebt euch ihr uralten Tore, und der König der Ehre wird einziehen.',
        10: 'Wer ist [es], dieser König der Ehre? JHWH der Heerscharen (Zebaot), Er ist der König der Ehre! Sela.',
    },
    26: {
        1: 'Von David. Verschaffe mir Recht (Richte mich, Hilf mir) JHWH, denn ich bin in meiner Vollkommenheit gewandelt (gegangen). Und auf JHWH habe ich vertraut und ich wanke (falle) nicht.',
        2: 'Prüfe (Teste) mich, JHWH, erprobe (versuche) mich, teste (verfeinere, veredele) meine Nieren und mein Herz (Inneres).',
        3: 'Denn deine Güte (Gnade) [ist] vor meinen Augen und ich gehe (wandle) in deiner Treue (Wahrheit, Standfestigkeit).',
        4: 'Ich saß nicht bei eitlen (falschen, inhaltlosen) Männern und mit etwas verheimlichenden ging (kam, verkehrte) ich nicht.',
        5: 'Ich hasste die Versammlung (Zusammenkunft) der Schlechten (Bösen), und bei (mit) den Frevlern (Gottlosen, Kriminellen) saß ich nicht (zusammen).',
        6: 'Ich wasche mein Handflächen (Hände) in Unschuld, und ich umschreite deinen Altar, JHWH.',
        7: 'um ein Danklied hören zu lassen in [lauter] Stimme und um alle deine Wunder zu erzählen (predigen, verkündigen).',
        8: 'JHWH, ich liebe den Ort (die Stätte) deines Hauses, und den Standort (Ort) der Wohnung deiner Herrlichkeit (Ehre).',
        9: 'Raffe meine Seele (mein Leben) nicht mit den Sündern, und meine Leben (Lebendigkeit) nicht mit den Männern des Blutes (Mördern),',
        10: 'denn an ihren Händen [ist] Schandtat, ihre rechte Hand ist voll von (angefüllt mit) Bestechung (Geschenk).',
        11: 'Und ich gehe wandle (gehe) in Vollkommenheit, erlöse mich und sei mir gnädig!',
        12: 'Mein Fuß stand aufrichtig (auf ebenem Boden), in Versammlungen (Zusammenkünften) preise (segne, lobe) ich JHWH.',
    },
    27: {
        1: 'Von David. JHWH ist mein Licht und meine Rettung (Heil, Hilfe), vor wem sollte ich mich fürchten? JHWH ist meines Lebens Schutzburg, vor wem sollte ich mich ängstigen?',
        2: 'Wenn Übeltäter sich mir nähern um mein Fleisch zu fressen, meine Bedränger und meine Feinde, so sind sie es, die straucheln und fallen.',
        3: 'Wenn sich ein Heer gegen mich lagert, so fürchtet sich mein Herz nicht, wenn sich auch Krieg gegen mich erhebt, trotzdem bin ich ein Vertrauender.',
        4: 'Eins habe ich von JHWH erbeten, das suche ich: zu wohnen (bleiben) im Haus JHWH s alle Tage meines Lebens, um zu sehen die Freundlichkeit (Lieblichkeit, Schönheit) JHWH s und Prüfung (Unterscheidung) in seinem Tempel.',
        5: 'Denn er wird mich bergen in seiner Hütte am Tag des Unheils, er wird mich verbergen im Versteck seines Zeltes, auf einen Felsen wird er mich heben.',
        6: 'Nun wird mein Haupt sich erheben über meine Feinde rings um mich her. Opfer voller Jubel will ich opfern in seinem Zelt, ich will singen und spielen für JHWH.',
        7: 'Höre, JHWH, mit meiner Stimme rufe ich: Sei mir gnädig und antworte mir!',
        8: 'Zu dir sagt mein Herz: Sucht mein Angesicht! Dein Angesicht, JHWH, suche ich.',
        9: 'Verbirg dein Angesicht nicht vor mir, weise deinen Knecht nicht ab vor Zorn! Du bist meine Hilfe gewesen. Gib mich nicht auf und verlass mich nicht, Gott meines Heils!',
        10: 'Selbst wenn mein Vater und meine Mutter mich verlassen, JHWH nimmt mich auf.',
        11: 'Lehre mich, JHWH, deinen Weg, und leite mich auf deinem Pfad um meiner Feinde willen.',
        12: 'Gib mich nicht preis der Gier meiner Bedränger, denn falsche Zeugen sind gegen mich aufgestanden und der, der Unrecht (Unheil, Gewalttat) schnaubt.',
        13: 'Ach, wenn ich nicht vertraut habe zu sehen das Gute JHWH s im Land der Lebendigen...',
        14: 'Hoffe auf JHWH! Sei stark, dass er dein Herz stärke, und hoffe auf JHWH!',
    },
    29: {
        1: 'Ein Lied in Bezug auf David. Gebt Jhwh, Söhne Gottes, gebt Jhwh Ehre und Macht.',
        2: 'Gebt Jhwh Ehre seines Namens, betet an Jhwh in heiliger Pracht.',
        3: 'Die Stimme Jhwhs über den Wassern, der Gott der Ehre hat es donnern lassen, Jhwh über großen Wassern.',
        4: 'Die Stimme Jhwhs mit Kraft, die Stimme Jhwhs mit Pracht.',
        5: 'Die Stimme Jhwhs zerbricht Zedern und Jhwh zerschmetterte die Zedern des Libanon.',
        6: 'Und er ließ sie hüpfen wie ein Kalb, Libanon und Sirjon wie ein Kalb des Wildstieres.',
        7: 'Die Stimme Jhwhs spaltet Feuerflammen.',
        8: 'Die Stimme Jhwhs lässt die Wüste kreißen, kreißen lässt Jhwh die Wüste Kadesch.',
        9: 'Die Stimme Jhwhs lässt große Bäume durcheinanderwirbeln und schälte Waldbäume ab und in seinem Tempel alle sagen „Ehre“.',
        10: 'Jhwh hat sich gesetzt auf die Flut und es setzte sich Jhwh, König für die Ewigkeit.',
        11: 'Jhwh gebe Macht seinem Volk, Jhwh segne sein Volk mit Frieden.',
    },
    30: {
        1: 'Ein Psalm (begleitetes Lied). Ein Lied zur Tempelweihe (Einweihung des Hauses) von (für, über, nach Art von) David',
        2: 'Ich will dir dafür danken, JHWH, dass (dich preisen/erhöhen, denn) du mich herausgeschöpft (emporgezogen) hast und dass du meine Feinde (meinen Feind) sich nicht über mich (meine meinigen Feinde sich nicht) freuen (triumphieren) lassen hast.',
        3: 'JHWH, mein Gott (JHWH, du bist mein Gott.), ich schrie zu dir um Hilfe (schrie zu dir, rief dich an) Und du hast mich geheilt (damit du mich heilst, als ich zu dir schrie, hast du mich geheilt).',
        4: 'JHWH, du hast mich (meine Seele) aus dem Scheol (aus der Unterwelt, aus der Totenwelt) heraufgeholt, du hast mich erweckt (mich leben lassen) aus den zur Grube Hinabgefahrenen (bewahrt vom Hinabfahren).',
        5: 'Singt (spielt) JHWH, ihr seine Frommen, preist den Heiligen (seinen heiligen Namen, das Gedenken seiner Heiligkeit)!',
        6: '{Oh!,} (Denn) [Nur] einen Augenblick lang währt sein Zorn, ein Leben lang währt seine Huld. {Oh!,} (Denn) Bleibt auch das Weinen (das Weinen bleibt) über Nacht (am Abend, verbringt man die Nacht auch weinend) [ist] doch am Morgen (und am Morgen ist) Jauchzen.',
        7: 'Als ich in meiner Sorglosigkeit sprach: „Niemals werde ich wanken!“',
        8: 'weil du ([und] als du), JHWH ({ JHWH }), mich in deiner Gunst standhafter als die starken (sicheren) Berge gemacht hast, verbargst du dein Gesicht (wandtest du dein Gesicht ab) [und] ich wurde vernichtet (erschrak)',
        9: '[Und sprach:] „Ich will zu dir rufen, JHWH, und zu meinem Herrn (zu dir, meinem Herrn) flehen!',
        10: 'Welcher Gewinn [ist] in meinem Blut [und] in meinem Hinabfahren in den Schacht? Kann Lehm (Staub, können Tote) dich preisen? Kann er (können sie) deine Treue verkünden?',
        11: 'Höre (erhöre mich), JHWH, und sei mir gnädig! JHWH, sei mir Helfer!“',
        12: 'Da hast du (du hast) mir mein Klagen in Tanzen verwandelt, hast mir die Trauerkleidung ausgezogen und mich mit Freude bekleidet (gegürtet). Darum (so dass, damit) will ich ([meine] Leber, [meine] Herrlichkeit, [meine] Seele) dich besingen und nie (nicht) verstummen (schweigen); JHWH, mein Gott, auf ewig will ich dich preisen!',
    },
    31: {
        1: 'Für den Chormeister. Ein Psalm (begleitetes Lied) von (für) David.',
        2: 'Bei dir, JHWH, habe ich mich geborgen; ich will nicht zuschanden werden für immer, mit (in/ um..willen) deiner Gerechtigkeit rette mich.',
        3: 'Neige zu mir dein Ohr, eile, um mich zu befreien. Sei mir ein Fels der Zuflucht, eine feste Burg, um mich zu retten.',
        4: 'Denn mein Fels und meine Burg bist du, um deines Namens willen leite und führe mich.',
        5: 'Führe mich aus dem Netz, das sie mir heimlich legten, denn du bist meine Zuflucht.',
        6: 'In deine Hand befehle ich meinen Geist, du hast mich erlöst, du treuer Gott.',
        7: 'Ich hasse, die sich an die Nichtse des Nichts halten, ich vetraue aber auf JHWH.',
        8: 'Ich will frohlocken und mich freuen an deiner Treue (Gnade), weil du mein Elend gesehen hast, erkannt hast die Nöte meiner Seele.',
        9: 'Du hast mich nicht der Hand (Gewalt) des Feindes ausgeliefert, du hast meine Füße auf weiten Raum gestellt.',
        10: 'Sei mir gnädig, JHWH, denn mir ist angst, schwach geworden vor Gram ist mein Auge, meine Seele und mein Leib.',
        11: 'Im Kummer schwindet dahin mein Leben, meine Jahre vergehen mit Seufzen. Meine Kraft ist ermattet durch mein Elend und schwach geworden sind meine Gebeine.',
        12: 'Allen meine Feinden bin ich zum Spott geworden und mehr noch meinen Nachbarn, ein Schrecken denen, die mir vertraut sind. Die mich auf der Straße sehen, fliehen vor mir.',
        13: 'Vergessen bin ich, wie ein Toter aus dem Sinn, bin geworden wie ein zerbrochenes Gefäß.',
        14: 'Ich höre das Zischeln der Menge, Grauen ringsum, wenn sie sich gegen mich verschwören, darauf sinnen, mir das Leben zu nehmen.',
        15: 'Ich aber vertraue auf dich, JHWH, ich spreche: Du bist mein Gott.',
        16: 'In deiner Hand stehen meine Zeiten, rette mich aus der Hand (Gewalt) meiner Feinde und vor meinen Verfolgern.',
        17: 'Lass leuchten dein Angesicht über deinem Diener, hilf mir um deiner Treue willen.',
        18: 'JHWH, ich will nicht zuschanden werden, denn ich habe zu dir gerufen. Zuschanden werden sollten die Frevler, heulend ins Totenreich fahren.',
        19: 'Verstummen sollen die Lippen der Lüge, die frech reden gegen den Gerechten, mit Hochmut und Geringschätzung.',
        20: 'Wie groß ist deine Güte, die du aufgespart hast für die, die dich fürchten, die du gegenüber den Menschen denen erweist, die Zuflucht suchen bei dir.',
        21: 'Du beschirmst sie im Schutz deines Angesichts vor der Zusammenrottung der Menschen, du birgst sie in einer Hütte vor dem Streit der Zungen.',
        22: 'Gepriesen sei JHWH, denn wunderbar hat er mir seine Treue erwiesen in einer befestigten Stadt.',
        23: 'Ich aber sprach bei meinem Aufgeschrecktsein: Ich bin verstoßen vor deinen Augen. Doch du hast die Stimme meines Flehens gehört, als ich zu dir schrie.',
        24: 'JHWH liebt all seine Getreuen. Die Getreuen behütet JHWH, doch über den Rest vergilt er dem, der Hochmut übt. Seid stark, dass er euer Herz stärke, ihr alle, die ihr hofft auf JHWH.',
    },
    33: {
        6: 'Durch das Wort JHWH s wurden die Himmel gemacht und durch den Hauch (Geist) seines Mundes ihr ganzes Heer (all ihr Heer).',
    },
    42: {
        1: 'Ein Kunstlied für den Musikmeister (Lehrgedicht für den Chorleiter, Andachtslied für die Liturgie) von den Korachiten (für die Nachkommen des Korach).',
        2: 'Wie eine Hirschkuh (ein Hirschbulle) Wasserbäche herbeisehnt (verlangt, ruft), so sehnt sich mein ganzes Wesen (verlangt meine Lebenskraft, ruft meine Kehle) nach dir (zu dir), Gott.',
        3: 'Alles, was in mir ist, (meine Lebenskraft, meine Kehle) durstet nach dir, Gott, nach dem lebendigen Gott: Wann werde (darf) ich [zu ihm] kommen, dass ich in Gottes Gegenwart trete?',
        4: 'Es sind mir [nämlich] meine Tränen zur [einzigen] Speise geworden, Tag und Nacht, denn sie fragen mich (wenn man sagt) zu mir jeden Tag: „Wo ist dein Gott?“',
        5: 'Ich will mich erinnern und mit meiner ganzen Existenz trauern: Ich gehe [in einer] großen Menschenmenge zu Gottes Haus mit Jubelruf und Lobgesang in einer feiernden Menge.',
    },
    50: {
        1: 'Ein Psalm (begleitetes Lied) von (für) Asaf. Gott, Gott, JHWH, hat geredet und ruft die Erde (das Land) vom Aufgang der Sonne bis zu ihrem Untergang.',
    },
    51: {
        1: 'Für den Chormeister. Ein Psalm (begleitetes Lied) von (für) David,',
        2: 'als der Prophet Natan zu ihm kam, nachdem er zu Batseba gegangen war.',
        3: 'Sei mir gnädig, Gott, nach deiner Treue, nach dem Maß deiner Mutterliebe tilge meine Vergehen!',
        4: 'Wasche mich ganz (viel = rein) von meiner Schuld und fege mich rein von meiner Sünde.',
        5: 'Denn meine Vergehen kenne ich und mein Fehler ist ständig mein Gegenüber.',
        6: 'An dir allein habe ich gesündigt, und ich habe Böses in deinen Augen getan; so bist du gerecht in deinem Sprechen, rein bist du in deinem Richten.',
        7: 'Sieh, in Sünde bin ich gekreißt worden, und in Sünde hat mich meine Mutter gebrunstet.',
        8: 'Sieh, an Wahrheit hast du Gefallen, tief im Verborgenen und im Geheimen tust du mir Weisheit kund.',
        9: 'Entsündige mich mit Ysop und ich werde rein, wasche mich, und ich werde weißer als Schnee.',
        10: 'Lass mich Freude und Wonne hören, frohlocken werden die Gebeine, die du zerschlagen hast.',
        11: 'Verbirg dein Angesicht vor meinen Sünden und tilge alle meine Vergehen!',
        12: 'Schaffe mir, Gott, ein reines Herz und gib mir einen neuen, beständigen Geist.',
        13: 'Verstoße mich nicht von deinem Angesicht (aus deiner Gegenwart) und deinen heiligen Geist nimm nicht von mir!',
        14: 'Bringe mir wieder die Freude deiner Rettung und stärke mich mit einem willigen Geist.',
        15: 'Die Abtrünnigen will ich deine Wege lehren und die Sünder kehren um zu dir.',
        16: 'Rette mich vor Blutschuld, Gott, du Gott meiner Rettung, dann (so) wird meine Zunge jubeln über deine Gerechtigkeit.',
        17: 'Herr, mache (tue) meine Lippen auf, und mein Mund wird deinen Ruhm verkünden.',
        18: 'Denn an Schlachtopfern hast du keinen Gefallen, und wollte ich Brandopfer bringen, dann (so) willst du sie nicht.',
        19: 'Das Opfer, das Gott gefällt, ist ein zerbrochener Geist, ein zerbrochenes und zerschlagenes Herz wirst du, Gott, nicht verachten. Tue Zion Gutes nach deinem Wohlgefallen, baue die Mauern Jerusalems! Dann wirst du Gefallen haben an rechten Opfern, an Brandopfern und Ganzopfern, dann wird man Stiere darbringen auf deinem Altar.',
    },
    53: {
        1: "''Für den Chorleiter (Dirigenten, Singenden, Musizierenden; [Vorzutragen vom] Vorsteher [über das Ritual]) '' `al-machalat. ''Ein Lehrgedicht (?) von (für, über, nach Art von) David.''",
        2: 'Es sagt (sagte) [der] Narr in seinem Herzen (es sagte sich der Narr):„Es gibt keinen Gott!“Sie begehen und verbrechen (begingen und verbrachen) Untat [Es gibt (gab)] keinen, [der] Gutes tut.',
        3: 'Gott beugte (beugt) sich (blickt?) vom Himmel herab Über [die] Menschenkinder, Um zu sehen, [ob] es gibt einen Klugen,Einen Gott-Sucher (einen Klugen, [der] Gott sucht):',
        4: '„Sie alle sind (waren) abgewichen,Sämtlich sind (waren) sie verdorben. Keinen [gibt (gab) es], [der] Gutes tut;Keinen. Auch nicht einen [einzigen].',
        5: 'Wissen [denn] nicht [s] [die] Übel-Täter, [Die] mein Volk fressen? Sie fressen Brot, [Doch] Gott rufen sie nicht an.“',
        6: 'Da erschraken sie einen Schrecken, [Wie es] nie [zuvor] Schrecken gab, Denn Gott zerstreute die Knochen des bei dir Lagernden;Du machtest [ihn] zuschanden, denn Gott verwarf sie. Möge es doch vom Zion Rettung für Israel geben! Wenn Gott das Geschick (die Gefangenschaft) seines Volkes wendet,Möge Jakob jubeln, Israel sich freuen!',
    },
    67: {
        1: 'Für den obersten Musiker (Chorleiter, Dirigenten, Aufseher, vorzusingen). Mit Saiteninstrumenten (fröhlicher Musik, Zupfinstrumenten). Ein Psalm (begleitetes Lied). Ein Lied.',
        2: 'Gott sei uns gnädig (erbarme sich über uns, sei uns wohlgesinnt) und segne uns! Er lasse sein Gesicht bei (auf, über) uns scheinen, – Sela –',
        3: 'damit (dann) auf der Erde (im Land) dein Weg erkannt [wird], unter allen Völkern (Nationen) deine rettende Kraft (Hilfe, Rettung, dein Eingeifen, Heil).',
        4: '[Die] Völker sollen (mögen, werden) dich preisen (bekennen, dir danken), Gott, [die] Völker sollen (mögen, werden) dich preisen {sie} alle!',
        5: '[Die] Völker (Völkerschaften) sollen (mögen, werden) sich freuen und singen, denn du richtest (wirst richten) [die] Völker gerecht ([mit] Gerechtigkeit), und [die] Völker (Völkerschaften) auf der Erde (im Land) führst (geleitest, regierst; wirst führen) du {sie}. Sela',
        6: '[Die] Völker sollen (mögen, werden) dich preisen (bekennen, dir danken), Gott, [die] Völker sollen (mögen, werden) dich preisen {sie} alle!',
        7: '[Das] Land ([die] Erde) hat (gibt) seinen Ertrag (ihre Frucht) gegeben. Es segne uns (segnet uns; wird, möge uns segnen) Gott, unser Gott! Es segne uns (möge, wird uns segnen, segnet uns) Gott, so dass (damit, und) alle Enden der Erde (die ganze Welt) ihn fürchten!',
    },
    68: {
        20: 'Gelobt (gepriesen, gesegnet) sei der Herr Tag für Tag, er trägt für uns, Gott [ist] für uns Heil (Hilfen, Rettung). Sela.',
        21: 'Gott [ist] für uns Gott zum Heil (der Rettungen), und bei JHWH Adonai [sind] die Auswege (Rettungen) vom Tod.',
    },
    73: {
        1: 'Ein Psalm (begleitetes Lied) von (für) Asaf. Lauter Güte ist Gott gegen Israel, gegen die, die reinen Herzens sind.',
        2: 'Ich aber wäre beinahe ausgeglitten mit meinen Füßen, um ein Haar wären meine Füße ins Wanken geraten.',
        3: 'Denn ich ereiferte mich über die Prahler, als ich sah, dass es den Frevlern gut geht.',
        4: 'Sie leiden keine Qualen bis zu ihrem Tod und fett ist ihr Leib.',
        5: 'Von der Mühsal der Sterblichen sind sie frei, sie werden nicht geplagt wie andere Menschen.',
        6: 'Darum ist ihr Hochmut ihr Halsgeschmeide, Gewalttat das Gewand, das sie umhüllt.',
        7: 'Sie sehen kaum aus den Augen vor fett, ihr Herz quillt über vor bösen Plänen.',
        8: 'Bösartig höhnen und reden sie, gewalttätig reden sie von oben herab.',
        9: 'Sie reißen ihr Maul auf bis an den Himmel, und ihre Zunge hat auf der Erde freien Lauf.',
        10: 'Darum wendet sich sein Volk ihnen zu, in vollen Zügen schlürfen sie Wasser.',
        11: 'Sie sagen: Wie sollte JHWH es wissen, gibt es ein Wissen bei dem Höchsten?',
        12: 'Sieh, das sind die Frevler, immer im Glück häufen sie Reichtum.',
        13: 'Ganz umsonst hielt ich mein Herz rein, wusch ich meine Hände in Unschuld.',
        14: 'Ich war geplagt jeden Tag, Morgen für Morgen traf mich Züchtigung.',
        15: 'Hätte ich gesagt: So will ich auch reden!, dann hätte ich Generationen deiner Söhne verraten.',
        16: 'Dann dachte (sann) ich nach, um es zu verstehen, Qual war es in meinen Augen,',
        17: 'bis ich zum Heiligtum Gottes kam und acht hatte auf ihr Ende.',
        18: 'Du stellst sie auf schlüpfrigen Boden, du lässt sie ins Leere fallen.',
        19: 'Wie werden sie zum Entsetzen im Nu, sie verschwinden, nehmen ein Ende mit Schrecken.',
        20: 'Wie einen Traum nach dem Erwachen, Herr, so verachtest du, wenn du aufwachst, ihr Bild.',
        21: 'Als mein Herz verbittert war und ich stechenden Schmerz in den Nieren spürte,',
        22: 'da war ich ein Narr und hatte keine Einsicht, dumm wie ein Vieh war ich vor dir.',
        23: 'Nun aber bleibe ich stets bei dir, du hältst mich an meiner rechten Hand.',
        24: 'Nach deinem Ratschluss leitest du mich, und danach (hernach) nimmst du mich auf in Herrlichkeit.',
        25: 'Wen hätte ich im Himmel? Bin ich bei dir, so begehre ich nichts auf Erden.',
        26: 'Mögen mein Leib und mein Herz verschmachten, der Fels meines Herzens und mein Teil ist JHWH auf ewig.',
        27: 'Denn sieh, die dir fern sind, kommen um, du vernichtest jeden, der dich treulos verlässt.',
        28: 'Mein Glück aber ist es, Gott nahe zu sein; bei Gott, JHWH, habe ich meine Zuflucht. Alle deine Werke will ich verkünden.',
    },
    82: {
        1: 'Ein Psalm (begleitetes Lied) von (für) Asaf: Gott (Elohim) steht in der Versammlung Els (Gottesversammlung), inmitten der Götter hält er Gericht:',
        2: '„Wie lange wollt ihr ungerecht richten (regieren) und die Angesichte der Frevler erheben? - Sela.',
        3: 'Verhelft zum Recht dem Schwachen und der Waise, dem Elenden und Bedürftigen schafft Gerechtigkeit!',
        4: 'Befreit den Schwachen und Armen, aus der Hand der Frevler rettet (ihn)!“',
        5: 'Nicht erkennen sie und nicht verstehen sie, in der Dunkelheit laufen sie hin und her. Es wanken alle Grundfesten der Erde.',
        6: 'Ich habe gesagt: „Götter seid ihr und Söhne des Höchsten, ihr alle.',
        7: 'Jedoch wie ein Mensch werdet ihr sterben und wie einer von den Obersten (Heeroberste, Fürsten) werdet ihr fallen.“',
        8: 'Erhebe dich Gott (Elohim)! Richte die Erde, denn du hast zum Erbbesitz alle Völker!',
    },
    88: {
        1: 'Ein Gesang. Ein Lied. Von den Söhnen des Korach. Für den Musikleiter. Zu singen nach Machalat. Ein Maskil. Von Heman, dem Esrachiter.',
        2: 'JHWH, Gott meiner Hilfe (Heils, Glücks), ich habe geschrien (gejammert) [am] Tag und in der Nacht vor dir.',
        3: 'Es komme vor dein Angesicht mein Gebet, neige dein Ohr zu meinem Flehen (Schreien, Jubel)!',
        4: 'Denn satt von Bosheit (Übeln) [ist] meine Seele, und mein Leben reicht [an] den Scheol.',
        5: 'Ich bin gerechnet zu denen, die in die Grube (Grab, Zisterne) gestiegen sind. Ich bin wie ein Mann ohne Hilfe (Stärke).',
        6: 'Unter den Toten frei [gelassen] wie Durchbohrte (Getötete), die im Grab liegen, derer du nicht gedenkst (um die du dich nicht kümmerst). Zudem (ferner) [sind] sie von deiner Hand getrennt (abgeschnitten).',
        7: 'Du hast mich gelegt (gesetzt) in die unterste Grube, in dunkle Orte (Finsternisse), in Tiefen.',
        8: 'Auf mich stemmt sich (über mich kommt) dein Zorn (Glut) und durch alle deine [brechenden] Wellen hast du mich niedergedrückt (gedemütigt). Sela.',
        9: 'Du hast meine Vertrauten (Freunde) von mir entfernt, du hast mich hingestellt (gesetzt) als Greuel (Abscheu) für sie. [Ich bin] ein Zurückgehaltener (Verhinderter) und kann nicht herausgehen.',
        10: 'Mein Auge verschmachtet vor (wegen) Elend (Leiden), ich rufe (schreie) zu dir, JHWH, den ganzen Tag. Ich breite aus vor (zu) dir meine Hand.',
        11: 'Wirst du an den Toten Wunder tun oder werden die Geister auf (er) stehen und dich loben?',
        12: 'Wird man im Grab von deiner Güte erzählen?',
        13: 'Werden deine Wunder in der Dunkelheit bekannt und deine Gerechtigkeit im Land des Vergessens?',
        14: 'Und ich rufe [um Hilfe] zu dir, JHWH, und am Morgen (in der Frühe) soll (wird) mein Gebet dir entgegentreten.',
        15: 'Warum, JHWH, verwirfst du meine Seele, verbirgst dein Angesicht vor mir?',
        16: 'Elend [bin] ich und todkrank von Jugend [an]. Ich ertrage deine Schrecken, ich bin ratlos.',
        17: 'Die Gluten deines Zornes (Zorngluten) haben mich überströmt, deine Schrecknisse haben mich vernichtet.',
        18: 'Sie umfließen (umgeben, umkreisen) mich wie Wasser den ganzen Tag, sie umringen mich alle zusammen (allesamt, beisammen). Du hast von mir entfernt [liebenden] Freund und [nahen] Verwandten (Stammesgenosse, Freund). Meine Vertrauten [sind] Finsternis.',
    },
    90: {
        1: 'Ein Gebet von Mose, dem Mann Gottes: Mein Herr (Herr), eine [sichere] Wohnung (Zufluchtsort) bist du für uns gewesen (bist du, warst du) von Generation (Zeitalter, Zeit, Geschlecht, Zeitspanne) zu Generation.',
        2: 'Bevor [die] Berge geboren waren (wurden) und du die Erde und die [irdische] Welt hervorgebracht (geboren) hattest (hervorbrachtest), {und} von Ewigkeit zu Ewigkeit bist du Gott (bist du, Gott).',
        3: 'Du lässt [den] Menschen zum Staub zurückkehren und sprichst: „Kehrt zurück (kehrt um), ihr Kinder des Menschen (Adams Söhne, Menschenkinder)!“',
        4: 'Denn (ja) tausend Jahre [sind] in deinen Augen wie [der] gestrige Tag, wenn er vergangen ist, oder (und) eine Wache in der Nacht (Nachtwache).',
        5: 'Du schwemmst sie weg, sie sind [wie] Schlaf (Du schwemmst sie weg [wie] Schlaf), am Morgen wie Gras, [das] aufsprosst (sie sind am Morgen wie Gras, [das] aufsprosst).',
        6: 'Am Morgen blüht (grünt) es und sprosst auf (blüht), zum Abend verwelkt und verdorrt (vertrocknet) es.',
        7: 'Denn (ja) wir vergehen durch deinen Zorn (Gesicht), und durch deine Zorneshitze (Zorn, Grimm, Hitze) werden wir verstört.',
        8: 'Du stellst (hast gestellt) unsere Fehler (Missetaten, Ungerechtigkeiten) vor dich, unsere Geheimnisse (verborgenen [Dinge]; was wir verborgen haben) vor das Licht deiner Gegenwart (deines Gesichts).',
        9: 'Ja (denn), alle unsere Tage fahren dahin (verschwinden) (sind dahingefahren) durch deinen Zorn (Grimm), wir vollenden (haben vollendet) unsere Jahre wie einen Seufzer (Stöhnen).',
        10: 'Die Tage unserer Jahre, in ihnen [sind] siebzig Jahre, und mit Kraft (durch [deine] Kraft [unterstützt], wenn in Kraft) achtzig Jahre. {und} Ihr Stolz [ist] Mühe und Beschwerde (Unglück, Nichtigkeit, Last), denn (ja) er ist (vergeht) schnell vergangen und wir fliegen [davon] ([dahin]).',
        11: 'Wer erkennt die Stärke deines Zorns? {und} Wie die Furcht vor dir (deine Furcht) [ist] dein Grimm (Zorn) (und gemäß deiner Furcht deinen Grimm?).',
        12: 'Darum (also, so) lehre uns, unsere Tage zu zählen, damit (dann, und) wir ein Herz der Weisheit (weises Herz) bekommen (erlangen, gewinnen).',
        13: 'Kehre doch (Wende dich doch [zu uns]) zurück, JHWH! Wie lange (bis wann)? {und} Habe Mitleid mit deinen Knechten (Sklaven, Dienern)!',
        14: 'Sättige uns am Morgen [mit] deiner Güte (liebenden Treue, Gnade, Liebe), dann (so dass, damit; und) werden wir jubeln und uns freuen an allen unseren Tagen!',
        15: 'Erfreue uns so [viele] Tage, [wie] du uns bedrückt hast (hast Leiden lassen, gebeugt hast), [so viele] Jahre, [wie] wir Unglück (Böses, Unheil) gesehen haben!',
        16: 'Zeige (lass sehen) deinen Knechten (Sklaven, Dienern) dein Handeln und deine Herrlichkeit (Glanz, Majestät, Macht) ihren Kindern (Söhnen)!',
        17: 'Die Freundlichkeit (Gunst) des Herrn (meines Herrn), unseres Gottes [sei] über uns! {und} Das Werk unserer Hände festige über uns, und (ja) das Werk unserer Hände, festige es!',
    },
    91: {
        1: 'Wer im Schutz des Höchsten (Eljon) sitzt (wohnt), bleibt im Schatten des Allmächtigen (Schaddai).',
        2: 'Ich sage zu JHWH: Meine Zuflucht und meine Burg, mein Gott, ich vertraue auf ihn.',
    },
    93: {
        1: 'JHWH ist König (herrscht)! Mit Hoheit hat er sich (ist er) bekleidet; bekleidet hat sich JHWH, [mit] Macht (Stärke) hat er sich umgürtet. Ja (auch), fest [gegründet] ist (steht) die Welt (der Weltenkreis) nichts erschüttert sie (sie wird niemals/nicht wanken).',
        2: 'Dein Thron steht fest von Anfang (damals) [an] von (seit) Ewigkeit [bist] du.',
        3: 'Es erheben (haben erhoben) (sich) ([die]) Fluten (Ströme), JHWH, es erheben (haben erhoben) ([die]) Fluten (Ströme) ihre Stimme (ihren Klang), es {werden} erheben ([die]) Fluten (Ströme) ihr Brausen (Tosen).',
        4: 'Mehr als die Klänge (Stimmen) von vielen (großen) Gewässern (Wassern), gewaltiger (majestätischer, mächtiger) als die Wogen (das Brechen, die Brandung, die Brecher) des Meeres [ist] gewaltig (majestätisch, mächtig) (gewaltig (er) [ist]) JHWH in der Höhe.',
        5: 'Deine Ordnungen (Gesetze, Weisungen) stehen sehr fest; lieblich ist dein Haus Heiligkeit, JHWH, für die Länge der Tage (für alle Zeit).',
    },
    94: {
        1: 'Gott der Rache (der rächt, Vergeltung) JHWH, Gott der Rache (rächt, Vergeltung) erscheine (leuchte auf)!',
        2: 'Erhebe dich, Richter der Erde, zahle zurück (vergelte, gib) den Stolzen ihren Lohn.',
        3: 'Wie lange noch (Bis wann) sollen die Gottlosen, JHWH wie lange noch (bis wann) sollen die Gottlosen [noch] jubeln (prahlen)?',
        4: 'und so trotzig reden und alle Übeltäter prahlen?',
        5: 'Gott, sie zerstören (machen) dein Volk (kaputt).',
        6: 'Sie töten Witwen (Frauen) und Fremde. Sie töten (Und) auch die Kinder',
        7: 'Und sie sagen: „Gott sieht es nicht (und Gott will es nicht sehen).“',
        8: 'Aber vielleicht sieht Gott doch Alles?',
        9: 'Wenn Gott uns Ohren gemacht hat, kann er auch hören. Und wenn Gott uns Augen gemacht hat, kann er auch sehen.',
        10: 'Der die Heiden züchtigt, sollte der nicht strafen, Wenn Gott Alles gemacht hat, was wir wissen, dann weiss er das auch.',
        11: 'Gott kennt uns ganz genau.',
    },
    97: {
        1: 'JHWH ist König (herrscht als König). Die Erde soll jubeln! Die großen (vielen) Inseln sollen sich freuen!',
    },
    100: {
        1: 'Ein Psalm (begleitetes Lied) zum Dank (zum Dankopfer, zum Dankgottesdienst, Preis, Lob, Wechselgesang?). Jubelt (schreit vor Freude) (über) JHWH zu, du ganze Erde (du ganzes Land)!',
        2: 'Dient (feiert Gottesdienst, feiert, verehrt) JHWH in Freude (Fröhlichkeit, Lustigkeit) kommt (hinein) vor ihn (in seine Wohnung, in sein Heiligtum) in Freudengeschrei (Freudenliedern)',
        3: 'Erkennt (Bekennt), dass (: Wahrlich!, denn) JHWH Gott ist! Er hat uns erschaffen, sein sind wir (und nicht wir) [wir sind] sein Volk und die Herde seiner Weide.',
        4: 'Kommt (hinein) durch seine Tore (die Tore seiner Wohnung/seines Heiligtums) mit Danklied (Dankopfer, Loblied)! [Kommt (hinein)] in seine Höfe (die Höfe seiner Wohnung/seines Heiligtums) mit Lobgesang (Lobpreis)! Preist ihn, lobsingt (segnet) seinem Namen (ihm)!',
        5: '{Ja! (Denn) } JHWH ist gut! Für immer ist (währt) seine Huld und von Generation zu Generation ist (währt) seine Treue (Verlässlichkeit)!',
    },
    104: {
        1: "'' ([Von (für, nach Art von) David]) '' Preise, meine Seele, JHWH! JHWH, mein Gott, [du bist] ([ist]) sehr groß! Du bist bekleidet (hast dich bekleidet) mit Majestät und Herrlichkeit (majestätischer Herrlichkeit/Pracht),",
        2: '[Bist] mit Licht wie mit einem Mantel umhüllt (verhüllt, ein Eingehüllter), [Oh, du] [bists], der den Himmel wie eine Zeltdecke ausspannte (bist ausspannend),',
        3: '[Bist] der, der bälkte (zimmerte) im (mit) Wasser ein Obergemach [Bist] der, der dort Wolken [als] seinen Wagen (sein Fahrzeug) [hat], [Bist] der, der sich fortbewegt (bist [dich] fortbewegend) auf den Flügeln des Windes,',
        4: '[Bists], der macht (bist machend) zu seinen Boten Winde (seine Boten zu Winden),Zu seinen Dienern (Seine Diener [sind]) flammendes Feuer (Flamme [und] Feuer),',
        5: '[Bists,] der gründete (bist gründend, er gründete) die Erde auf ihre Fundamente, Damit sie nicht wanken wird auf immer und ewig.',
        6: 'Das Urmeer bedecktest du wie mit einem Gewand. Auf (über) den Bergen sollten Wasser stehen (sich stellen):',
        7: 'Vor deinem Schelten mussten (sollten) sie fliehen,Vor dem Klang deines Donnerns (deiner donnernden Stimme) mussten (sollten) sie fortlaufen,',
        8: 'Mussten (sollten) hinaufziehen [auf] Berge,Mussten (sollten) hinabsteigen [in] TälerZum Ort, den du ihnen gegründet hast.',
        9: '[Die] Grenze, [die] du gesetzt hast, dürfen sie nicht übertreten, Dürfen nicht zurückkehren, um die Erde zu bedecken (dürfen die Erde nicht wieder bedecken).',
        10: '[Oh, du] [bist] der, der entsendet Quellen in Wadis – Sie sollen (müssen) zwischen [den] Bergen fließen (gehen),',
        11: 'Sollen (müssen) alle wilden Tiere (alle Tiere dessen vom Berge) tränken,Es sollen [selbst] die Wildesel ihren Durst brechen können (sollen/müssen stillen).',
        12: 'Über ihnen wohnt das Gevögel des Himmels,Von zwischen den Felsen (Zweigen) geben sie [ihre] Stimme –,',
        13: '[Bists,] der tränkt die Berge von seinen Obergemächern: Von der Frucht deiner Werke (deines Arbeitens) soll die Erde sitt (satt) werden.',
        14: '[Bists,] der sprossen lässt das Gras für ViehUnd Pflanzen zum Nutzen (für den Ackerbau) der Menschen: Damit [dieser] Brot aus der Erde hervorbringe (um hervorzubringen...),',
        15: 'Soll Menschenherzen Wein erfreuen; Damit ihr Gesicht von Öl glänzt (mehr glänzt als Öl), Soll Menschenherzen Brot (Nahrung) stärken.',
        16: 'Es sollen sitt werden (sättigen) die Bäume des Feldes (JHWH s),Die Libanon-zedern, die er gepflanzt hat.',
        17: 'Dort (, auf denen) sollen Vöglein nisten,Der Habicht (Storch?, Reiher?) in ihren Wipfeln (auf Zypressen) sein Haus [haben].',
        18: 'Die hohen Berge [sollen] den Steinböcken [gehören],Die Felsen den Klippdachsen Zuflucht [sein].',
        19: 'Er machte den Mond für Festzeiten, Die Sonne kennt ihren Untergang.',
        20: 'Du willst Finsternis setzen,Es soll Nacht werden, In ihr sollen alle Waldtiere schleichen (pirschen):',
        21: 'Die Junglöwen brüllen nach Beute, Um zu fordern von Gott ihre Speise.',
        22: 'Die Sonne soll scheinen,Sie sollen sich sammeln und in ihre Höhlen legen.',
        23: 'Der Mensch soll an sein Werk gehenUnd an seine Arbeit bis zum Abend.',
        24: 'Wie zahlreich (groß) [sind] deine Werke, JHWH! Sie alle hast du mit Weisheit gemacht! Voll ist die Erde mit seinem Besitz,',
        25: 'So auch das Meer: (Dies – das Meer – [ist], dort [ist] das Meer:) groß und weit {die Seiten}: Dort [gibt es] Gewürm ohne Zahl,Kleine Tiere und große.',
        26: 'Dort schwimmen Schiffe, (schwimmen dort gleich Schiffen.) [Schwimmt der] Leviathan, den du gebildet, um mit ihm Spaß zu haben (damit er darinnen Spaß habe).',
        27: 'Sie alle warten auf dich,dass du [ihnen] gibst Nahrung zur rechten Zeit.',
        28: 'Du gibst ihnen (Gibst du ihnen,...) [Nahrung], sie sammeln [sie].Du öffnest deine Hand (Öffnest du deine Hand,...), sie werden gesättigt mit Gutem.',
        29: 'Du verbirgst dein Gesicht (verbirgst du dein Gesicht,...), sie werden vernichtet (erschrecken),Du nimmst ihren Atem (Geist), sie sterben (hauchen aus) Und zu ihrem Staub kehren sie zurück.',
        30: 'Du sendest deinen Atem (Geist) aus, sie werden geschaffen;Du erneuerst das Gesicht (die Oberfläche) der Erde.',
        31: 'Es währe die Herrlichkeit (Pracht) JHWH s auf ewig,Es freue sich JHWH über seine Werke!',
        32: 'Der auf die Erde blickt, so dass sie bebt, Er rührt die Berge an, sie rauchen.',
        33: 'Ich will singen JHWH mein [ganzes] Leben,ich will lobsingen meinem Gott meine [ganze] Dauer,',
        34: 'Möge ihm angenehm sein meine Rede (mein Sinnen),Ich will mich freuen über JHWH!',
        35: 'Es mögen (werden) schwinden Sünder von der ErdeUnd Frevler, von Dauer [mögen (werden)] sie nicht [sein]. Preise, meine Seele, JHWH! –Hallelujah (Preist Jah!, Preist JHWH!)!',
    },
    109: {
        4: 'Für meine Liebe feinden (klagen sie mich an) sie mich an. Aber ich [bin] Gebet (Bittgebet, Anrufung).',
        5: '{Und} sie legen auf mich Böses statt (für) Gutes – {und} Hass (Feindschaft) statt (für) meiner Liebe:',
        6: 'Übergebe ihn (bestelle für ihn) einem Gottlosen (Frevler)! Und ein Ankläger (Widersacher, Gegner) soll stehen auf seiner rechten Seite (zu seiner Rechten).',
        7: 'Während er gerichtet wird (den/einen Rechtsstreit führt), soll er herausgehen (hervorgehen) [als] ein Gottloser (Frevler), und sein Gebet (Bittgebet, Anrufung) soll werden zur Sünde.',
    },
    110: {
        1: 'Von (Für; [Über den neuen]) David. Ein Psalm (begleitetes Lied). Spruch JHWH s für meinen Herrn: Setze dich zu meiner Rechten, bis ich deine Feinde gemacht habe zum Schemel deiner Füße.',
        2: 'Den Stab deiner Macht (deinen machtvollen Stab) wird JHWH aus Zion ausstrecken, herrsche inmitten deiner Feinde.',
        3: 'Dein Volk ist Bereitwilligkeit am Tage deiner Macht. In heiliger Pracht aus dem Schoß der Morgenröte der Tau deiner Jugend ist dein.',
        4: 'Geschworen hat JHWH und es gereut ihn nicht: Du bist Priester in Ewigkeit (für immer) nach der Weise Melchisedeks (des gerechten Königs?).',
        5: 'Der Herr/ JHWH zu deiner Rechten zerschmettert Könige am Tag seines Zorns.',
        6: 'Er richtet unter den Völkern, er füllt Leichen. Er zerschmettert das Haupt auf der weiten Erde.',
        7: 'Auf dem Weg trinkt er aus dem Bach, darum hebt er das Haupt.',
    },
    117: {
        1: 'Lobt JHWH, alle Völker! Preist (ehrt) ihn, alle Stämme (Ethnien, Geschlechter),',
        2: 'denn mächtig (groß) ist uns zugunsten seine Güte (Gnade, Liebe, Gewogenheit), und JHWH s Treue (Beständigkeit, Zuverlässigkeit) hat ewig Bestand ([bleibt] für immer). Halleluja (Lobt Jah)!',
    },
    118: {
        1: 'Preist JHWH, denn er ist gut, ewig währt seine Treue.',
        2: 'Es spreche Israel: Ewig währt seine Treue.',
        3: 'Es spreche das Haus Aaron: Ewig währt seine Treue.',
        4: 'Sprechen sollen, die JHWH fürchten: Ewig währt seine Treue.',
        5: 'Aus der Bedrängnis rief ich zu JHWH, JHWH erhörte mich in weitem Raum.',
        6: 'JHWH ist für mich, ich fürchte mich nicht. Was könnten die Menschen mir antun?',
        7: 'JHWH ist für mich als mein Helfer, weiden wird sich mein Blick an denen, die mich hassen.',
        8: 'Besser ist es, bei JHWH Zuflucht zu suchen, als Menschen zu vertrauen.',
        9: 'Besser ist es, bei JHWH Zuflucht zu suchen, als Fürsten zu vertrauen.',
        10: 'Alle Völker umringen mich, im Namen JHWH s aber wehre ich sie ab.',
        11: 'Sie umkreisen, sie umringen mich, im Namen JHWH s aber wehre ich sie ab.',
        12: 'Wie Bienen umkreisen sie mich; wie ein Dornenfeuer verlöschen sie, im Namen JHWH s wehre ich sie ab.',
        13: 'Du hast mich hart gestoßen zu fallen, JHWH aber hat mir geholfen.',
        14: 'Meine Kraft und meine Stärke ist JHWH, und er wurde mir zur Rettung.',
        15: 'Klang des Jubels und der Rettung ist in den Zelten der Gerechten. Es macht Kraft (Heil; Gewaltiges) die Rechte (rechte Hand) JHWH s.',
        16: 'Die Rechte (rechte Hand) JHWH s erhöht, es macht Kraft (Heil; Gewaltiges) die Rechte (rechte Hand) JHWH s.',
        17: 'Ich werde nicht sterben, sondern leben und die Taten JHWH s verkünden.',
        18: 'JHWH hat mich stark zurechtgewiesen, dem Tod aber nicht preisgegeben.',
        19: 'Macht (Tut) mir auf die Tore der Gerechtigkeit. Ich will durch sie einziehen, um JHWH zu danken.',
        20: 'Dies ist das Tor JHWH s, die Gerechten ziehen hier ein.',
        21: 'Ich will dir danken, denn du hast mir geantwortet und bist für mich zur Rettung geworden.',
        22: 'Der Stein, den die Bauleute verworfen haben, ist zum Eckstein geworden.',
        23: 'Durch JHWH ist es geschehen, wunderbar ist es in unseren Augen.',
        24: 'Dies ist der Tag, den JHWH gemacht hat, wir wollen jauchzen und uns an ihm freuen!',
        25: 'Ach JHWH, hilf! Ach JHWH, lass gelingen!',
        26: 'Gesegnet sei, wer kommt im Namen JHWH s. Wir segnen euch vom Haus JHWHs.',
        27: 'JHWH ist Gott, er gab uns Licht. Schmückt das Fest mit Zweigen bis zu den Hörnern des Altars!',
        28: 'Du bist mein Gott! Ich will dir danken, mein Gott, ich will dich erheben!',
        29: 'Preist JHWH, denn er ist gut, ewig währt seine Treue!',
    },
    120: {
        1: 'Ein Lied der Wallfahrten (großen Aufstiege, aufsteigenden Frauen) Zu JHWH rief (schrie; rufe) ich in (wegen) meiner Not (Elend) und er antwortete (antwortet).',
        2: 'JHWH, rette meine Person doch vor lügenden Lippen (Lippen der Lüge), vor einer täuschenden Zunge!',
        3: 'Was soll [man] dir geben und was soll [man] dir noch antun, [du] täuschende Zunge?',
        4: 'Die scharfen Pfeile eines Kriegers mit glühenden (brennenden) Kohlen aus Ginster!',
        5: 'Weh mir, denn ich lebe (habe gelebt) [als Ausländer in] Meschech, ich wohne (habe gewohnt) bei den Zelten von Kedar!',
        6: 'Lange (zu lange) hat meine Person bei (den) Friedensverächtern (Friedenshassern; Verächtern des Friedens) gewohnt (wohnt)!',
        7: 'Ich [liebe] Frieden (Harmonie; [bin] friedfertig), aber wenn ich spreche, [sind] sie für den Krieg ([bereit] zum Krieg).',
    },
    126: {
        1: 'Ein Wallfahrtslied. Als zurückführte JHWH die Gefangenen Zions, waren wir wie Träumende.',
        2: 'Da wurde voll Lachens unser Mund und unsere Zunge [voll] Jubels. Da sagen sie in (unter) den Völkern: Große Dinge hat getan JHWH mit diesen.',
        3: 'Es hat getan JHWH große Dinge mit uns. Wir sind freudig.',
        4: 'Kehre um (wende), JHWH, unser Gefängnis, wie die Ströme im Südland.',
        5: 'Die mit Tränen Säenden - mit Jubel werden sie ernten.',
        6: 'Er geht hin und weinend trägt er eine Saat-Tasche. Er kommt zurück mit Jubel tragend seine Garben.',
    },
    131: {
        1: 'Ein Wallfahrtslied (Stufenlied, Reiselied). Von (für, über, nach Art von) David. JHWH, mein Herz (ich) ist (war) nicht (nie) [mehr] anmaßend (hochmütig, hybrid), {und} meine Augen (ich) sind (waren) nicht (nie) [mehr] vermessen (stolz, hoffärtig, hoch erhoben) {und} ich gehe (ging) nicht (nie) [mehr] nach (gehe um mit, gehe in) [für mich zu] großen Zielen (Großem, großen Dingen) und für mich zu wunderbaren (für mich unmöglichen, zu schwierigen) Dingen.',
        2: 'Nein, nicht [mehr]! Sondern (Gewiss, wenn nicht) ich habe meine Seele (mich) besänftigt (beschwichtigt) und beruhigt: Wie ein entwöhntes Kind (ein Kleinkind, das Kleinkind) auf (auf [dem Schoß], auf [den Schultern]) seiner Mutter (mir, seiner Mutter), Wie ein solches entwöhntes Kind (Kleinkind, wie das Kind, das auf mir ist,) [ist] auf mir meine Seele.',
        3: 'Warte (hoffe) [auch du], Israel, auf JHWH - von nun an und für immer!',
    },
    133: {
        1: 'Ein Lied der Wallfahrten (großen Aufstiege, aufsteigenden Frauen). Von (Für) David. Siehe wie gut und wie schön es ist, wenn Brüder einträchtig zusammen (beieinander) wohnen (siedeln).',
        2: 'Wie gutes Öl auf dem Kopf (Haupt), das auf den Bart hinunter (herunter) fällt (läuft, rinnt), auf den Bart Aarons, der herunter (hinunter) fällt (läuft, wallt) auf den Saum (Mund) seiner Gewänder',
        3: 'Wie der Tau des Hermon, der herunter (hinunter) fällt (läuft, rinnt) auf die Berge Zions. Denn dort hin befiehlt JHWH den Segen, Leben bis in Ewigkeit (für immer).',
    },
    134: {
        1: 'Ein Lied der Wallfahrten (großen Aufstiege, aufsteigenden Frauen). Siehe (Wohlan, Auf), preiset (segnet, lobet) JHWH, alle Diener (Knechte, Sklaven) JHWH s, die im Haus JHWHs stehen (die Stehenden) in den Nächten.',
        2: 'Hebt eure Hände zum Heiligtum (in Heiligkeit) und preiset (segnet, lobet) JHWH.',
        3: 'JHWH möge dich segnen (preisen, loben) vom (aus) Zion, der Himmel und Erde gemacht hat.',
    },
    138: {
        1: 'Von (für, über, nach Art von) David. Ich will dich mit (von) meinem ganzem Herzen preisen (preise, werde preisen), gegenüber (vor) Göttern ([der] himmlischen Versammlung, Gott; in deinem Tempel) will ich ich dir lobsingen (ein Lob auf dich singen, dir musizieren; singe, werde singen)!',
        2: 'Ich will mich in Richtung (in) deines heiligen Tempels niederwerfen (beten, mich verbeugen; werfe mich nieder, werde mich niederwerfen) und deinen Namen (dich) für deine Liebe (Güte, Gnade, liebende Treue, Bundestreue) und {für deine} Treue (Verlässlichkeit, Ehrlichkeit) preisen (bekennen, danken; preise, werde preisen), denn (dass, ja) du hast dein Wort (Versprechen) noch über all dein Ansehen (Namen) hinaus bekannt gemacht (gerühmt, groß/erhaben gemacht; machst bekannt)!',
        3: 'Als (An [dem] Tag, [an dem]) ich gerufen habe (rufe), hast du mir geantwortet (antwortest du mir, hast du mich erhört), hast mich ermutigt (ermutigst) mit {meiner} Seelenkraft (hast mir in meiner Seele Kraft gegeben)!',
        4: 'Dich, JHWH, sollen (werden) alle Könige der Erde (des Landes) anerkennen (preisen, danken), wenn (weil) sie die Worte (Worte) [aus] deinem Mund gehört haben (hören),',
        5: 'und {sie sollen (werden) } von (auf) JHWH s Walten (Wegen) singen. Wie (denn, ja) groß [ist] JHWH s Herrlichkeit!',
        6: 'Obwohl (ja, denn), JHWH erhaben (erhöht) [ist], {und} nimmt er (sieht; wird wahrnehmen) den Unbedeutenden (Geringen, Niedrigen; Niedriges) wahr, doch (und, aber) den Wichtigen (Hochmütigen, Hohen; der Hohe) kennt (erkennt; wird kennen) (und [er ist] hoch, [aber] er kennt) er aus der Ferne (Entfernung; von fern).',
        7: 'Wenn (Auch wenn, obwohl) ich mitten in (durch) Gefahr (Schwierigkeiten, Bedrängnis, Gefahr) hineinlaufe (stecke, mich befinde; hineinlaufen werde), bewahrst du mein (erhältst du mich am; wirst/mögest du bewahren) Leben trotz der (Gegen die) Wut meiner Feinde! Du streckst deine [linke] Hand aus (wirst/mögest ausstrecken), und deine rechte Hand rettet mich (hilft mir; wird/möge mich retten)!',
        8: 'JHWH wird meine Sache führen (es für mich vollbringen, mich rächen; möge führen/führt meine Sache)! JHWH, deine Güte (Liebe, liebende Treue, Gnade, Bundestreue) [währt (reicht)] bis in Ewigkeit (ewig)! Die Werke (das Werk, Wirken) deiner Hände gib (Du wirst aufgeben; lass im Stich, lass ab von, lass fallen) niemals auf!',
    },
    145: {
        1: 'Ein Lobgesang. Von David. Ich will dich erheben, mein Gott, der König, und ich will preisen deinen Namen bis in alle Ewigkeit.',
        2: 'Den ganzen Tag über will ich dich preisen und ich will loben deinen Namen bis in alle Ewigkeit.',
        3: 'Groß ist JHWH und sehr zu loben und seine Größe ist nicht zu erforschen.',
        4: 'Generation für Generation wird deine Werke rühmen und deine Machttaten werden sie verkünden.',
        5: 'Reden sollen sie von der herrlichen Pracht deiner Majestät und deine Wunder will ich erzählen.',
        6: 'Und sie sollen sprechen von der Kraft deiner furchtbaren Taten und deine Größe will ich erzählen.',
        7: 'Das Gedächtnis deiner großen Güte sollen sie wecken und deine Gerechtigkeit werden sie jubelnd preisen.',
        8: 'Gnädig und barmherzig ist JHWH, langsam im Zorn und groß an Güte.',
        9: 'JHWH ist gut gegen alle und sein Erbarmen ist über alle seine Werke.',
        10: 'Es werden dich loben, JHWH, alle deine Werke und deine Frommen werden dich preisen.',
        11: 'Sie werden von der Herrlichkeit deines Reiches sprechen und von deinen Machttaten werden sie reden,',
        12: 'Um den Menschensöhnen seine Machttaten kundzutun und die prachtvolle Herrlichkeit seines Reiches.',
        13: 'Dein Reich ist ein Reich für alle Ewigkeit und deine Herrschaft dauert von allem Geschlecht zu Geschlecht.',
        14: 'JHWH ist ein Stützender für alle Fallenden, er ist ein Aufrichtender für alle Niedergebeugten.',
        15: 'Augen (von) allen warten auf dich und du gibst ihnen Speise zu seiner Zeit.',
        16: 'Du tust deine Hand auf und sättigst alles Lebendige nach Wohlgefallen.',
        17: 'JHWH ist gerecht in allen seinen Wegen und treu in allen seinen Werken.',
        18: 'Nahe ist JHWH all denen, die ihn rufen, all denen die ihn in Wahrheit anrufen.',
        19: 'Er erfüllt das Verlangen von denen, die ihn fürchten. Ihr schreien hört er und er rettet sie.',
        20: 'JHWH bewahrt alle, die ihn lieben, aber alle Frevler vertilgt er.',
        21: 'Mein Mund soll das Lob JHWH aussprechen und alles Fleisch soll seinen heiligen Namen preisen bis in alle Ewigkeit.',
    },
    146: {
        1: 'Halleluja! (Lobt JH!) Meine Seele, lobe JHWH!',
        2: 'Ich will JHWH in meinem Leben loben. Ich will Gott singen, solange ich bin.',
        3: 'Vertraut nicht auf Fürsten und nicht auf einen Menschensohn, bei dem keine Hilfe ist.',
        4: 'Sein Geist geht aus. Er geht zurück zu seiner Erde. An dem Tag gehen seine Gedanken verloren.',
        5: 'Wohl dem, dessen Hilfe der Gott Jakobs ist, dessen Hoffnung auf JHWH, seinem Gott, ist,',
        6: 'welcher Himmel und Erde gemacht hat, das Meer und alles, was in ihnen ist; der, der ewiglich Treue hält.',
        7: 'Einer, der Recht schafft denen, die bedrückt werden; einer, der Brot gibt denen, die Hunger haben. JHWH befreit die Gefesselten.',
        8: 'JHWH lässt Blinde sehen. JHWH richtet Gebeugte auf. JHWH liebt die Gerechten.',
        9: 'JHWH beschützt Fremde. Waise und Witwe richtet er wieder auf. Aber den Weg der Gottlosen krümmt er.',
        10: 'JHWH wird ewig König sein, dein Gott, Zion, von Generation zu Generation. Halleluja! (Lobt JH!)',
    },
    149: {
        1: 'Halleluja (Preist Jah, Preist JHWH)! Singt JHWH ein neues Lied, [singt] seinen Lob (-preis, Ruhm) in der Gemeinde (Truppe) der Getreuen (Frommen, Heiligen?)',
        2: 'Israel soll sich seines Schöpfers freuen, ob ihres Königs sollen Zion’s Söhne (Kinder) frohlocken (jubeln, jauchzen).',
        3: 'Sie sollen seinen Namen (ihn) preisen mit (im) Tanz (Reigen, Isisklapper?), mit Tamburin und Zither sollen sie ihm spielen,',
        4: 'Denn (Ja!, damit?) JHWH hat Wohlgefallen an seinem Volk, die (seine) Unterdrückten (Gebeugten, Niedrigen, Demütigen, Armen, Hilflosen, Duldern) schmückt (verherrlicht, krönt?) er mit ([seinem]) Sieg (Heil, Rettung).',
        5: 'Jauchzen sollen die Getreuen (Frommen, Heiligen (?)) ob [ihrer] Herrlichkeit (Herrlichen, Mächtigen), jubeln sollen sie auf ihren Lagern, (-)',
        6: 'Loblieder (-preisungen, Rühmungen) Gottes (auf Gott) [sollen sein] in ihrer Kehle (ihrem Mund, singend) Und (gleich einem, (und) das ist) ein zweischneidiges (scharfes) Schwert [soll sein] in ihrer Hand, (-)',
        7: 'auf dass er Rache übe (zum Ausüben von Rache) an den Völkern (Nationen), und Strafgericht (Züchtigung) an den Nationen (Völkern);',
        8: 'auf dass er binde (zum Binden) ihre Könige (Herrscher) mit Fesseln (Handschellen), und ihre Fürsten (Adeligen, Edlen, Beamten) mit eisernen Ketten (Fußketten);',
        9: 'auf dass er Gericht halte (spreche, zum Gericht-Halten, zum Halten von geschriebenen Recht) wie geschrieben [steht]. Er (Das) ist (bringt) Ehre (Herrlichkeit, Pracht, Ruhm, der Mächtige) seinen (für seine, seiner) Getreuen (Frommen). Halleluja (Preist Jah, Preist JHWH)!',
    },
}
